VALUES (1695, 'Uma paciente, 28 anos, com histórico de múltiplos episódios de dor pélvica e febre, é diagnosticada com doença inflamatória pélvica (DIP). Ela manifesta preocupação com sua fertilidade futura. Qual é o principal fator relacionado à DIP que pode comprometer a fertilidade dessa paciente?', 'Formação de abscessos ovarianos que prejudicam a ovulação.', 'Aumento do risco de gravidez ectópica, devido à obstrução tubária.', 'Redução da reserva ovariana causada pela inflamação crônica.', 'Comprometimento endometrial pela destruição dos receptores hormonais.', NULL, 'B', NULL, NULL, '[]', 2025, 'ABC', NULL, 'SP', 'MASTOLOGIA', 20, 1, NULL, NULL, '2026-04-08T21:50:21.32491+00:00', '2026-08-06T18:52:01.536155+00:00', FALSE, NULL, '[{"code":"D000292","term":"Doença Inflamatória Pélvica","name_en":"Pelvic Inflammatory Disease","tree_ids":["C01.635.500","C12.050.351.500.056.750","C12.100.250.056.750"],"hierarchy_path":"Doenças › C01.635.500","branches":[{"tree_id":"C01.635.500","hierarchy_path":"Doenças › C01.635.500"},{"tree_id":"C12.050.351.500.056.750","hierarchy_path":"Doenças › C12.050.351.500.056.750"},{"tree_id":"C12.100.250.056.750","hierarchy_path":"Doenças › C12.100.250.056.750"}],"search_method":"text","role":"primary","scope_note":"Espectro inflamatório envolvendo o trato genital superior feminino e os tecidos de sustentação. Geralmente é devida à infecção ascendente por organismos a partir da endocérvix. A infecção pode estar limitada ao útero (ENDOMETRITE), às TUBAS UTERINAS (SALPINGITE), aos ovários (OOFORITE), aos ligamentos de sustentação (PARAMETRITE) ou afetar vários dos apêndices uterinos acima. Esta inflamação pode provocar alteração funcional e infertilidade."},{"code":"D007247","term":"Infertilidade Feminina","name_en":"Infertility, Female","tree_ids":["C12.050.351.500.498","C12.100.250.498","C12.100.750.350"],"hierarchy_path":"Doenças › C12.050.351.500.498","branches":[{"tree_id":"C12.050.351.500.498","hierarchy_path":"Doenças › C12.050.351.500.498"},{"tree_id":"C12.100.250.498","hierarchy_path":"Doenças › C12.100.250.498"},{"tree_id":"C12.100.750.350","hierarchy_path":"Doenças › C12.100.750.350"}],"search_method":"text","role":"primary","scope_note":"Habilidade diminuída ou ausente da fêmea concluir a concepção."},{"code":"D011271","term":"Gravidez Ectópica","name_en":"Pregnancy, Ectopic","tree_ids":["C12.050.703.733"],"hierarchy_path":"Doenças › C12.050.703.733","branches":[{"tree_id":"C12.050.703.733","hierarchy_path":"Doenças › C12.050.703.733"}],"search_method":"text","role":"primary","scope_note":"Afecção com risco de morte materna na qual a IMPLANTAÇÃO DO EMBRIÃO ocorre fora da cavidade do ÚTERO. A maioria das gestações ectópicas (mais de 96 por cento) ocorre nas TUBAS UTERINAS e é conhecida como GRAVIDEZ TUBÁRIA. Podem ocorrer em outros locais, como no COLO DO ÚTERO, OVÁRIO e cavidade abdominal (GRAVIDEZ ABDOMINAL)."},{"code":"D065851","term":"Reserva Ovariana","name_en":"Ovarian Reserve","tree_ids":["G08.686.210.249","G08.686.628"],"hierarchy_path":"Fenômenos Biológicos › G08.686.210.249","branches":[{"tree_id":"G08.686.210.249","hierarchy_path":"Fenômenos Biológicos › G08.686.210.249"},{"tree_id":"G08.686.628","hierarchy_path":"Fenômenos Biológicos › G08.686.628"}],"search_method":"text","role":"secondary","scope_note":"Capacidade do ovário de fornecer ovos viáveis."},{"code":"D017699","term":"Dor Pélvica","name_en":"Pelvic Pain","tree_ids":["C23.888.592.612.944","F02.830.816.444.841","G11.561.790.444.841"],"hierarchy_path":"Doenças › C23.888.592.612.944","branches":[{"tree_id":"C23.888.592.612.944","hierarchy_path":"Doenças › C23.888.592.612.944"},{"tree_id":"F02.830.816.444.841","hierarchy_path":"Psiquiatria e Psicologia › F02.830.816.444.841"},{"tree_id":"G11.561.790.444.841","hierarchy_path":"Fenômenos Biológicos › G11.561.790.444.841"}],"search_method":"text","role":"secondary","scope_note":"Dor na região pélvica de origem genital e não genital."},{"code":"D005334","term":"Febre","name_en":"Fever","tree_ids":["C23.888.119.344"],"hierarchy_path":"Doenças › C23.888.119.344","branches":[{"tree_id":"C23.888.119.344","hierarchy_path":"Doenças › C23.888.119.344"}],"search_method":"text","role":"secondary","scope_note":"Elevação anormal da temperatura corporal, geralmente como resultado de um processo patológico."}]', NULL, NULL, NULL, NULL, NULL, '{"competencias":[{"competencia":"Identificação de mecanismo da doença","conteudos":[],"id":"95","justificativa":"Para responder corretamente, o candidato deve compreender o mecanismo pelo qual a DIP afeta a fertilidade, especificamente a obstrução tubária que leva à gravidez ectópica.","principal":false}],"novas_competencias":[]}', '{"temas":[{"tema":"Doença inflamatória pélvica","subtemas":["Doença inflamatória pélvica"],"principal":true},{"tema":"Infertilidade","subtemas":["Infertilidade"],"principal":false}],"tema_principal":"Doença inflamatória pélvica"}', '{"source":"backfill-missing-primary-meta","kept_count":6,"dismissed_at":null,"validated_at":"2026-07-30T18:06:49.577Z","primary_count":3,"removed_count":2,"review_reason":"Todos os termos candidatos foram removidos. O candidato ''Testes de Patência das Tubas Uterinas'' foi removido por não representar o conceito de ''Obstrução Tubária'' (condição vs. método diagnóstico). O candidato ''Abscesso Abdominal'' foi removido por ser semanticamente mais amplo e geograficamente impreciso que ''Abscesso Ovariano'' no contexto pélvico da questão, resultando na ausência de termos primários e secundários aprovados.","coerencia_geral":12,"needs_manual_review":false,"missing_primary_terms":false}'::jsonb, 25681, 597, '{"totals":{"by_agent":{"decs_classifier":{"calls":1,"input_tokens":1649,"total_tokens":3570,"output_tokens":55},"habilities_agent":{"calls":1,"input_tokens":8369,"total_tokens":8621,"output_tokens":252},"question_terms_validator":{"calls":1,"input_tokens":2825,"total_tokens":4355,"output_tokens":211},"question_themes_assigner":{"calls":1,"input_tokens":12838,"total_tokens":12917,"output_tokens":79}},"input_tokens":25681,"total_tokens":29463,"output_tokens":597,"thoughts_tokens":3185},"operations":[{"agent":"decs_classifier","model":"gemini-2.5-flash","input_tokens":1649,"total_tokens":3570,"output_tokens":55,"thoughts_tokens":1866},{"agent":"question_terms_validator","model":"gemini-2.5-flash","input_tokens":2825,"total_tokens":4355,"output_tokens":211,"thoughts_tokens":1319},{"agent":"question_themes_assigner","model":"gemini-2.5-flash","input_tokens":12838,"total_tokens":12917,"output_tokens":79},{"agent":"habilities_agent","model":"gemini-2.5-flash","input_tokens":8369,"total_tokens":8621,"output_tokens":252}],"updated_at":"2026-07-30T18:06:52.308Z","estimated_cost_usd":{"input_usd":0.007704,"total_usd":0.009197,"output_usd":0.001493}}'::jsonb)
