VALUES (1696, 'Uma paciente com diagnóstico de endometriose apresenta sintomas de dor crônica e alterações intestinais cíclicas, sugerindo comprometimento abdominal. Quais são os principais sítios abdominais onde a endometriose pode se manifestar, causando dor e outros sintomas?', 'Fundo de saco de Douglas, apêndice e ceco.', 'Fundo de saco de Douglas, ligamentos útero-sacros e intestino delgado.', 'Ligamentos largos, intestino delgado e vesícula biliar.', 'Ligamentos útero-sacros, ceco e fígado.', NULL, 'A', NULL, NULL, '[]', 2025, 'ABC', NULL, 'SP', 'MASTOLOGIA', 20, 2, NULL, NULL, '2026-04-08T21:50:21.32744+00:00', '2026-08-06T18:52:01.536155+00:00', FALSE, NULL, '[{"code":"D004715","term":"Endometriose","name_en":"Endometriosis","tree_ids":["C12.050.351.500.163","C12.100.250.163"],"hierarchy_path":"Doenças › C12.050.351.500.163","branches":[{"tree_id":"C12.050.351.500.163","hierarchy_path":"Doenças › C12.050.351.500.163"},{"tree_id":"C12.100.250.163","hierarchy_path":"Doenças › C12.100.250.163"}],"search_method":"text","role":"primary","scope_note":"Afecção na qual o tecido endometrial funcional está presente exteriormente ao ÚTERO. Frequentemente está restrito a PELVE envolvendo OVÁRIO, ligamentos, fundo-de-saco e o peritônio útero-vesical."},{"code":"D001065","term":"Apêndice","name_en":"Appendix","tree_ids":["A03.556.124.526.209.290","A03.556.249.249.209.290"],"hierarchy_path":"Anatomia › A03.556.124.526.209.290","branches":[{"tree_id":"A03.556.124.526.209.290","hierarchy_path":"Anatomia › A03.556.124.526.209.290"},{"tree_id":"A03.556.249.249.209.290","hierarchy_path":"Anatomia › A03.556.249.249.209.290"}],"search_method":"text","role":"secondary","scope_note":"Extensão do CECO, em forma de um tubo cego (semelhante a um verme)."},{"code":"D002432","term":"Ceco","name_en":"Cecum","tree_ids":["A03.556.124.526.209","A03.556.249.249.209"],"hierarchy_path":"Anatomia › A03.556.124.526.209","branches":[{"tree_id":"A03.556.124.526.209","hierarchy_path":"Anatomia › A03.556.124.526.209"},{"tree_id":"A03.556.249.249.209","hierarchy_path":"Anatomia › A03.556.249.249.209"}],"search_method":"text","role":"secondary","scope_note":"Bolsa cega (ou área em fundo-de-saco) do INTESTINO GROSSO, localizada abaixo da entrada do INTESTINO DELGADO. Apresenta uma extensão em forma de verme, o APÊNDICE vermiforme."},{"term":"Dor Pélvica","code":"D017699","tree_ids":["C23.888.592.612.944","F02.830.816.444.841","G11.561.790.444.841"],"hierarchy_path":"Doenças › C23.888.592.612.944","branches":[{"tree_id":"C23.888.592.612.944","hierarchy_path":"Doenças › C23.888.592.612.944"},{"tree_id":"F02.830.816.444.841","hierarchy_path":"Psiquiatria e Psicologia › F02.830.816.444.841"},{"tree_id":"G11.561.790.444.841","hierarchy_path":"Fenômenos Biológicos › G11.561.790.444.841"}],"scope_note":"Dor na região pélvica de origem genital e não genital.","name_en":"Pelvic Pain","search_method":"vector","role":"secondary"},{"term":"Intestinos","code":"D007422","tree_ids":["A03.556.124"],"hierarchy_path":"Anatomia › A03.556.124","branches":[{"tree_id":"A03.556.124","hierarchy_path":"Anatomia › A03.556.124"}],"scope_note":"Seção do canal alimentar que vai do ESTÔMAGO até o CANAL ANAL. Inclui o INTESTINO GROSSO e o INTESTINO DELGADO.","name_en":"Intestines","search_method":"vector","role":"secondary"}]', NULL, NULL, NULL, NULL, NULL, NULL, '{"temas":[{"tema":"Dor pélvica crônica","subtemas":["Dor pélvica crônica"],"principal":true}],"tema_principal":"Dor pélvica crônica"}', '{"source":"backfill-missing-primary-meta","kept_count":5,"dismissed_at":null,"validated_at":"2026-07-30T18:07:55.690Z","primary_count":1,"removed_count":1,"review_reason":"O termo primário ''Endometriose'' não foi fornecido como candidato DeCS. Os termos aprovados são secundários e não representam a entidade central da questão, necessitando de revisão manual para garantir a cobertura do conceito principal.","coerencia_geral":69,"needs_manual_review":false,"missing_primary_terms":false}'::jsonb, 2566