VALUES (1698, 'Um paciente com cirrose e hepatocarcinoma é avaliado para transplante hepático. Segundo os critérios de Barcelona, quais características do tumor permitem que o paciente seja considerado um candidato para transplante hepático?', 'Tumor único com diâmetro de até 5 cm ou até três nódulos com até 3 cm cada.', 'Tumor único com diâmetro até de 3 cm e ausência de invasão vascular.', 'Presença de dois nódulos menores que 3 cm cada e sem metástases.', 'Nódulo único de até 6 cm ou até quatro nódulos com até 2 cm cada.', NULL, 'A', NULL, NULL, '[]', 2025, 'ABC', NULL, 'SP', 'MASTOLOGIA', 20, 4, NULL, NULL, '2026-04-08T21:50:21.332793+00:00', '2026-08-06T18:52:01.536155+00:00', FALSE, NULL, '[{"code":"D006528","term":"Carcinoma Hepatocelular","name_en":"Carcinoma, Hepatocellular","tree_ids":["C04.557.470.200.025.255","C04.588.274.623.160","C06.301.623.160","C06.552.697.160"],"hierarchy_path":"Doenças › C04.557.470.200.025.255","branches":[{"tree_id":"C04.557.470.200.025.255","hierarchy_path":"Doenças › C04.557.470.200.025.255"},{"tree_id":"C04.588.274.623.160","hierarchy_path":"Doenças › C04.588.274.623.160"},{"tree_id":"C06.301.623.160","hierarchy_path":"Doenças › C06.301.623.160"},{"tree_id":"C06.552.697.160","hierarchy_path":"Doenças › C06.552.697.160"}],"search_method":"text","role":"primary","scope_note":"Neoplasia maligna primária de células hepáticas epiteliais. Abrange desde o tumor bem diferenciado com CÉLULAS EPITELIAIS, indistinguíveis dos HEPATÓCITOS normais até a neoplasia pouco diferenciada. As células podem ser uniformes, marcadamente pleomórficas, ou ainda, podem formar CÉLULAS GIGANTES. Vários esquemas classificatórios têm sido propostos."},{"code":"D016031","term":"Transplante de Fígado","name_en":"Liver Transplantation","tree_ids":["E02.095.147.725.490","E04.210.650","E04.936.450.490","E04.936.580.490"],"hierarchy_path":"Técnicas e Equipamentos Analíticos › E02.095.147.725.490","branches":[{"tree_id":"E02.095.147.725.490","hierarchy_path":"Técnicas e Equipamentos Analíticos › E02.095.147.725.490"},{"tree_id":"E04.210.650","hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.210.650"},{"tree_id":"E04.936.450.490","hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.936.450.490"},{"tree_id":"E04.936.580.490","hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.936.580.490"}],"search_method":"text","role":"primary","scope_note":"Transferência de uma parte do fígado ou do fígado inteiro, de um ser humano ou animal a outro."},{"code":"D008103","term":"Cirrose Hepática","name_en":"Liver Cirrhosis","tree_ids":["C06.552.630","C23.550.355.412"],"hierarchy_path":"Doenças › C06.552.630","branches":[{"tree_id":"C06.552.630","hierarchy_path":"Doenças › C06.552.630"},{"tree_id":"C23.550.355.412","hierarchy_path":"Doenças › C23.550.355.412"}],"search_method":"text","role":"primary","scope_note":"A doença hepática na qual a microcirculação normal, a anatomia vascular no geral, e a arquitetura hepática têm sido destruídas e alteradas de modo variado por septos fibrosos ao redor de nódulos parenquimatosos regenerados ou em regeneração."}]', NULL, NULL, NULL, NULL, NULL, NULL, '{"temas":[{"tema":"Cirrose","subtemas":["Cirrose"],"principal":true},{"tema":"Nódulos hepáticos","subtemas":["Nódulos hepáticos malignos"],"principal":false}],"tema_principal":"Cirrose"}', '{"source":"backfill-missing-primary-meta","kept_count":3,"dismissed_at":null,"validated_at":"2026-07-30T18:09:49.607Z","primary_count":3,"removed_count":0,"review_reason":"Nenhum descritor vetorial/API disponível para validação (apenas textuais ou lista vazia).","coerencia_geral":0,"needs_manual_review":true,"missing_primary_terms":false}'::jsonb, 22835, 282, '{"totals":{"by_agent":{"decs_classifier":{"calls":1,"input_tokens":1642,"total_tokens":3390,"output_tokens":25},"habilities_agent":{"calls":1,"input_tokens":8362,"total_tokens":8531,"output_tokens":169},"question_themes_assigner":{"calls":1,"input_tokens":12831,"total_tokens":12919,"output