INSERT INTO public.questions ("id", "statement", "option_a", "option_b", "option_c", "option_d", "option_e", "correct_answer", "explanation", "tags", "images", "exam_year", "exam_board", "exam_institution", "exam_region", "exam_type", "prova_id", "numero_na_prova", "areas_conhecimento", "assuntos", "created_at", "updated_at", "anulada", "decs_terms", "ai_decs_descriptors", "ai_decs_v2", "ai_decs_classified_text", "images_meta", "competencias", "temas", "ai_habilities", "ai_question_themes", "decs_validation_meta", "input_tokens", "output_tokens", "ai_token_usage")
VALUES (1699, 'Durante a realização de uma colectomia laparoscópica, um grampeador linear cortante é utilizado para a criação de anastomose. Qual das alternativas descreve corretamente uma vantagem do uso de suturas mecânicas em cirurgias minimamente invasivas e abertas?', 'Menor custo comparado às suturas manuais.', 'Maior flexibilidade de uso em anastomoses vasculares complexas.', 'Redução do tempo cirúrgico e do risco de vazamento em anastomoses intestinais.', 'Diminuição do risco de lesão térmica em tecidos próximos.', NULL, 'C', NULL, NULL, '[]', 2025, 'ABC', NULL, 'SP', 'MASTOLOGIA', 20, 5, NULL, NULL, '2026-04-08T21:50:21.334978+00:00', '2026-08-06T18:52:01.536155+00:00', FALSE, NULL, '[{"code":"D013528","term":"Grampeadores Cirúrgicos","name_en":"Surgical Staplers","tree_ids":["E07.858.700.750"],"hierarchy_path":"Técnicas e Equipamentos Analíticos › E07.858.700.750","branches":[{"tree_id":"E07.858.700.750","hierarchy_path":"Técnicas e Equipamentos Analíticos › E07.858.700.750"}],"search_method":"text","role":"primary","scope_note":"Aparelhos de fixação compostos de ligas aço-tântalo usados para fechar ferimentos operativos, especialmente da pele, que minimiza infecções por não introduzir um corpo estranho que conectaria regiões externas e internas do corpo."},{"code":"D000714","term":"Anastomose Cirúrgica","name_en":"Anastomosis, Surgical","tree_ids":["E04.035"],"hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.035","branches":[{"tree_id":"E04.035","hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.035"}],"search_method":"text","role":"primary","scope_note":"União cirúrgica ou passagem entre ductos, tubos ou vasos. Pode ser extremidade com extremidade, extremidade com borda, borda com extremidade ou borda com borda."},{"code":"D003082","term":"Colectomia","name_en":"Colectomy","tree_ids":["E04.210.896.001"],"hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.210.896.001","branches":[{"tree_id":"E04.210.896.001","hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.210.896.001"}],"search_method":"text","role":"primary","scope_note":"Ressecção cirúrgica de uma parte do cólon ou de todo o CÓLON."},{"code":"D010535","term":"Laparoscopia","name_en":"Laparoscopy","tree_ids":["E01.370.388.250.520","E04.502.250.520"],"hierarchy_path":"Técnicas e Equipamentos Analíticos › E01.370.388.250.520","branches":[{"tree_id":"E01.370.388.250.520","hierarchy_path":"Técnicas e Equipamentos Analíticos › E01.370.388.250.520"},{"tree_id":"E04.502.250.520","hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.502.250.520"}],"search_method":"text","role":"secondary","scope_note":"Procedimento em que um laparoscópio (LAPAROSCÓPIOS) é inserido através de uma pequena incisão próxima ao umbigo para examinar os órgãos abdominais e pélvicos na CAVIDADE PERITONEAL Se necessário, pode ser realizado biópsia ou cirurgia durante a laparoscopia."},{"code":"D061646","term":"Duração da Cirurgia","name_en":"Operative Time","tree_ids":["E04.614.374.500","N02.421.585.753.374.500"],"hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.614.374.500","branches":[{"tree_id":"E04.614.374.500","hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.614.374.500"},{"tree_id":"N02.421.585.753.374.500","hierarchy_path":"Saúde › N02.421.585.753.374.500"}],"search_method":"text","role":"secondary","scope_note":"Duração de um procedimento cirúrgico em horas e minutos."},{"code":"D007412","term":"Fístula Intestinal","name_en":"Intestinal Fistula","tree_ids":["C06.267.550","C06.405.469.471","C23.300.575.185.550"],"hierarchy_path":"Doenças › C06.267.550","branches":[{"tree_id":"C06.267.550","hierarchy_path":"Doenças › C06.267.550"},{"tree_id":"C06.405.469.471","hierarchy_path":"Doenças › C06.405.469.471"},{"tree_id":"C23.300.575.185.550","hierarchy_path":"Doenças › C23.300.575.185.550"}],"search_method":"text","role":"secondary","scope_note":"Passagem anatômica anormal entre o INTESTINO e qualquer segmento do intestino ou outro órgão. A fístula intestinal externa está conectada à PELE (fístula enterocutânea). A fístula intestinal interna pode estar conectada a vários órgãos, como ESTÔMAGO (fístula gastrocólica), TRATO BILIAR (fístula colecistoduodenal) ou BEXIGA URINÁRIA do TRATO URINÁRIO (fístula colovesical). Entre os fatores de risco estão os processos inflamatórios, câncer, tratamento por radiação e acidentes cirúrgicos (ERROS MÉDICOS)."},{"code":"D007420","term":"Intestino Grosso","name_en":"Intestine, Large","tree_ids":["A03.556.124.526","A03.556.249.249"],"hierarchy_path":"Anatomia › A03.556.124.526","branches":[{"tree_id":"A03.556.124.526","hierarchy_path":"Anatomia › A03.556.124.526"},{"tree_id":"A03.556.249.249","hierarchy_path":"Anatomia › A03.556.249.249"}],"search_method":"text","role":"secondary","scope_note":"Segmento do TRATO GASTRINTESTINAL INFERIOR, compreendendo o CECO, o COLO e o RETO."}]', NULL, NULL, NULL, NULL, NULL, '{"competencias":[{"competencia":"Comparação de eficácia entre intervenções","conteudos":[],"id":"124","justificativa":"A questão pede para identificar uma vantagem do uso de suturas mecânicas em comparação com suturas manuais, o que exige a avaliação e comparação da eficácia e segurança de diferentes técnicas cirúrgicas.","principal":true}],"novas_competencias":[]}', '{"temas":[{"tema":"Técnica cirúrgica e instrumental","subtemas":["Videocirurgia e laparoscopia"],"principal":true},{"tema":"Perioperatório","subtemas":["Complicações pós-operatórias e profilaxia de TEV"],"principal":false}],"tema_principal":"Técnica cirúrgica e instrumental"}', '{"source":"backfill-missing-primary-meta","kept_count":7,"dismissed_at":null,"validated_at":"2026-07-30T18:10:18.889Z","primary_count":3,"removed_count":0,"review_reason":"Nenhum descritor vetorial/API disponível para validação (apenas textuais ou lista vazia).","coerencia_geral":0,"needs_manual_review":true,"missing_primary_terms":false}'::jsonb, 22805, 368, '{"totals":{"by_agent":{"decs_classifier":{"calls":1,"input_tokens":1632,"total_tokens":2925,"output_tokens":47},"habilities_agent":{"calls":1,"input_tokens":8352,"total_tokens":8559,"output_tokens":207},"question_themes_assigner":{"calls":1,"input_tokens":12821,"total_tokens":12935,"output_tokens":114}},"input_tokens":22805,"total_tokens":24419,"output_tokens":368,"thoughts_tokens":1246},"operations":[{"agent":"decs_classifier","model":"gemini-2.5-flash","input_tokens":1632,"total_tokens":2925,"output_tokens":47,"thoughts_tokens":1246},{"agent":"question_themes_assigner","model":"gemini-2.5-flash","input_tokens":12821,"total_tokens":12935,"output_tokens":114},{"agent":"habilities_agent","model":"gemini-2.5-flash","input_tokens":8352,"total_tokens":8559,"output_tokens":207}],"updated_at":"2026-07-30T18:10:22.066Z","estimated_cost_usd":{"input_usd":0.006841,"total_usd":0.007761,"output_usd":0.00092}}'::jsonb)
