INSERT INTO public.questions ("id", "statement", "option_a", "option_b", "option_c", "option_d", "option_e", "correct_answer", "explanation", "tags", "images", "exam_year", "exam_board", "exam_institution", "exam_region", "exam_type", "prova_id", "numero_na_prova", "areas_conhecimento", "assuntos", "created_at", "updated_at", "anulada", "decs_terms", "ai_decs_descriptors", "ai_decs_v2", "ai_decs_classified_text", "images_meta", "competencias", "temas", "ai_habilities", "ai_question_themes", "decs_validation_meta", "input_tokens", "output_tokens", "ai_token_usage")
VALUES (1700, 'Um paciente com diagnóstico de esôfago de Barrett, confirmado por biópsia, com displasia de baixo grau, apresenta sintomas refratários de refluxo gastroesofágico apesar do uso de inibidores de bomba de prótons em dose máxima. Em que situação a cirurgia antirrefluxo é indicada para pacientes com esôfago de Barrett?', 'Em todos os pacientes com Barrett, independentemente dos sintomas ou da presença de displasia.', 'Apenas em pacientes com Barrett e displasia de alto grau, independentemente dos sintomas.', 'Em pacientes com Barrett e displasia de baixo grau, ou, até mesmo, sem displasia, que apresentam sintomas refratários ao tratamento medicamentoso.', 'Quando houver evidência de displasia de alto grau no esôfago de Barrett, independentemente dos sintomas.', NULL, 'C', NULL, NULL, '[]', 2025, 'ABC', NULL, 'SP', 'MASTOLOGIA', 20, 6, NULL, NULL, '2026-04-08T21:50:21.337258+00:00', '2026-08-06T18:52:01.536155+00:00', FALSE, NULL, '[{"code":"D001471","term":"Esôfago de Barrett","name_en":"Barrett Esophagus","tree_ids":["C04.834.154","C06.405.117.102"],"hierarchy_path":"Doenças › C04.834.154","branches":[{"tree_id":"C04.834.154","hierarchy_path":"Doenças › C04.834.154"},{"tree_id":"C06.405.117.102","hierarchy_path":"Doenças › C06.405.117.102"}],"search_method":"text","role":"primary","scope_note":"Afecção com lesão no revestimento do ESÔFAGO inferior em consequência de um refluxo ácido crônico (ESOFAGITE DE REFLUXO). Através do processo de metaplasia, as células escamosas são substituídas por um epitélio colunar semelhante ao do INTESTINO ou pela mucosa rosada do ESTÔMAGO. O epitélio colunar de Barret é um marcador de intenso refluxo e precursor do ADENOCARCINOMA do esôfago."},{"code":"D018662","term":"Fundoplicatura","name_en":"Fundoplication","tree_ids":["E04.210.390"],"hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.210.390","branches":[{"tree_id":"E04.210.390","hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.210.390"}],"search_method":"text","role":"primary","scope_note":"Mobilização da extremidade inferior do esôfago e plicatura do fundo do estômago em torno dele (envoltório fúndico), no tratamento da ESOFAGITE DE REFLUXO que pode associar-se com vários distúrbios, como hérnia de hiato. (Dorland, 28a ed)"},{"code":"D005764","term":"Refluxo Gastroesofágico","name_en":"Gastroesophageal Reflux","tree_ids":["C06.405.117.119.500.484"],"hierarchy_path":"Doenças › C06.405.117.119.500.484","branches":[{"tree_id":"C06.405.117.119.500.484","hierarchy_path":"Doenças › C06.405.117.119.500.484"}],"search_method":"text","role":"primary","scope_note":"Fluxo retrógrado de suco gástrico (ÁCIDO GÁSTRICO) e/ou conteúdos duodenais (ÁCIDOS E SAIS BILIARES, SUCO PANCREÁTICO) para dentro do ESÔFAGO distal, frequentemente devido à incompetência do ESFÍNCTER ESOFÁGICO INFERIOR."},{"code":"D054328","term":"Inibidores da Bomba de Prótons","name_en":"Proton Pump Inhibitors","tree_ids":["D27.505.519.389.848"],"hierarchy_path":"Compostos Químicos e Drogas › D27.505.519.389.848","branches":[{"tree_id":"D27.505.519.389.848","hierarchy_path":"Compostos Químicos e Drogas › D27.505.519.389.848"}],"search_method":"text","role":"secondary","scope_note":"Compostos que inibem ATPASE TROCADORA DE HIDROGÊNIO-POTÁSSIO. São utilizados como ANTIULCEROSOS e, às vezes, no lugar de ANTAGONISTAS DOS RECEPTORES H2 DE HISTAMINA para REFLUXO GASTROESOFÁGICO."},{"code":"D001706","term":"Biópsia","name_en":"Biopsy","tree_ids":["E01.370.225.500.384.100","E01.370.225.998.054","E01.370.388.100","E04.074","E05.200.500.384.100","E05.200.998.054","E05.242.384.100"],"hierarchy_path":"Técnicas e Equipamentos Analíticos › E01.370.225.500.384.100","branches":[{"tree_id":"E01.370.225.500.384.100","hierarchy_path":"Técnicas e Equipamentos Analíticos › E01.370.225.500.384.100"},{"tree_id":"E01.370.225.998.054","hierarchy_path":"Técnicas e Equipamentos Analíticos › E01.370.225.998.054"},{"tree_id":"E01.370.388.100","hierarchy_path":"Técnicas e Equipamentos Analíticos › E01.370.388.100"},{"tree_id":"E04.074","hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.074"},{"tree_id":"E05.200.500.384.100","hierarchy_path":"Técnicas e Equipamentos Analíticos › E05.200.500.384.100"},{"tree_id":"E05.200.998.054","hierarchy_path":"Técnicas e Equipamentos Analíticos › E05.200.998.054"},{"tree_id":"E05.242.384.100","hierarchy_path":"Técnicas e Equipamentos Analíticos › E05.242.384.100"}],"search_method":"text","role":"secondary","scope_note":"Remoção e avaliação patológica de amostras do corpo vivo."}]', NULL, NULL, NULL, NULL, NULL, '{"competencias":[{"competencia":"Mudança terapêutica","conteudos":[],"id":"103","justificativa":"A questão aborda a situação de sintomas refratários ao tratamento medicamentoso máximo, exigindo a decisão de mudar a abordagem terapêutica para cirurgia.","principal":false}],"novas_competencias":[]}', '{"temas":[{"tema":"Doença do refluxo gastroesofágico","subtemas":["Doença do refluxo gastroesofágico"],"principal":true},{"tema":"Doenças benignas do esôfago","subtemas":["Doenças benignas do esôfago"],"principal":false},{"tema":"Câncer de esôfago","subtemas":["Câncer de esôfago"],"principal":false}],"tema_principal":"Doença do refluxo gastroesofágico"}', '{"source":"backfill-missing-primary-meta","kept_count":5,"dismissed_at":null,"validated_at":"2026-07-30T18:10:56.388Z","primary_count":3,"removed_count":1,"review_reason":"Todos os termos candidatos fornecidos foram excluídos por falta de equivalência semântica real, resultando na ausência de termos no conjunto final.","coerencia_geral":23,"needs_manual_review":false,"missing_primary_terms":false}'::jsonb, 25699, 563, '{"totals":{"by_agent":{"decs_classifier":{"calls":1,"input_tokens":1687,"total_tokens":3007,"output_tokens":43},"habilities_agent":{"calls":1,"input_tokens":8407,"total_tokens":8679,"output_tokens":272},"question_terms_validator":{"calls":1,"input_tokens":2729,"total_tokens":3994,"output_tokens":128},"question_themes_assigner":{"calls":1,"input_tokens":12876,"total_tokens":12996,"output_tokens":120}},"input_tokens":25699,"total_tokens":28676,"output_tokens":563,"thoughts_tokens":2414},"operations":[{"agent":"decs_classifier","model":"gemini-2.5-flash","input_tokens":1687,"total_tokens":3007,"output_tokens":43,"thoughts_tokens":1277},{"agent":"question_terms_validator","model":"gemini-2.5-flash","input_tokens":2729,"total_tokens":3994,"output_tokens":128,"thoughts_tokens":1137},{"agent":"question_themes_assigner","model":"gemini-2.5-flash","input_tokens":12876,"total_tokens":12996,"output_tokens":120},{"agent":"habilities_agent","model":"gemini-2.5-flash","input_tokens":8407,"total_tokens":8679,"output_tokens":272}],"updated_at":"2026-07-30T18:10:59.363Z","estimated_cost_usd":{"input_usd":0.00771,"total_usd":0.009117,"output_usd":0.001408}}'::jsonb)
