INSERT INTO public.questions ("id", "statement", "option_a", "option_b", "option_c", "option_d", "option_e", "correct_answer", "explanation", "tags", "images", "exam_year", "exam_board", "exam_institution", "exam_region", "exam_type", "prova_id", "numero_na_prova", "areas_conhecimento", "assuntos", "created_at", "updated_at", "anulada", "decs_terms", "ai_decs_descriptors", "ai_decs_v2", "ai_decs_classified_text", "images_meta", "competencias", "temas", "ai_habilities", "ai_question_themes", "decs_validation_meta", "input_tokens", "output_tokens", "ai_token_usage")
VALUES (1701, 'Um paciente submetido à colecistectomia laparoscópica desenvolve drenagem persistente de bile pelo dreno no pós-operatório. A colangiografia confirma uma fístula biliar de baixo débito sem coleções intra-abdominais. Qual é o tratamento inicial mais indicado para essa condição?', 'Realização de drenagem percutânea guiada por imagem à beira-leito.', 'Administração de antibióticos por via oral e observação ambulatorial.', 'Colocação de prótese biliar por CPRE, para reduzir a pressão ductal.', 'Cirurgia emergencial de revisão com fechamento da fístula.', NULL, 'C', NULL, NULL, '[]', 2025, 'ABC', NULL, 'SP', 'MASTOLOGIA', 20, 7, NULL, NULL, '2026-04-08T21:50:21.33968+00:00', '2026-08-06T18:52:01.536155+00:00', FALSE, NULL, '[{"code":"D001658","term":"Fístula Biliar","name_en":"Biliary Fistula","tree_ids":["C06.267.150","C23.300.575.185.150"],"hierarchy_path":"Doenças › C06.267.150","branches":[{"tree_id":"C06.267.150","hierarchy_path":"Doenças › C06.267.150"},{"tree_id":"C23.300.575.185.150","hierarchy_path":"Doenças › C23.300.575.185.150"}],"search_method":"text","role":"primary","scope_note":"Passagem anormal em qualquer órgão do trato biliar ou entre órgãos biliares e outros órgãos."},{"code":"D002760","term":"Colangiopancreatografia Retrógrada Endoscópica","name_en":"Cholangiopancreatography, Endoscopic Retrograde","tree_ids":["E01.370.350.700.715.200.200","E01.370.372.200.200","E01.370.372.250.200","E01.370.388.250.250.160","E04.210.240.160","E04.502.250.250.160"],"hierarchy_path":"Técnicas e Equipamentos Analíticos › E01.370.350.700.715.200.200","branches":[{"tree_id":"E01.370.350.700.715.200.200","hierarchy_path":"Técnicas e Equipamentos Analíticos › E01.370.350.700.715.200.200"},{"tree_id":"E01.370.372.200.200","hierarchy_path":"Técnicas e Equipamentos Analíticos › E01.370.372.200.200"},{"tree_id":"E01.370.372.250.200","hierarchy_path":"Técnicas e Equipamentos Analíticos › E01.370.372.250.200"},{"tree_id":"E01.370.388.250.250.160","hierarchy_path":"Técnicas e Equipamentos Analíticos › E01.370.388.250.250.160"},{"tree_id":"E04.210.240.160","hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.210.240.160"},{"tree_id":"E04.502.250.250.160","hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.502.250.250.160"}],"search_method":"text","role":"primary","scope_note":"Endoscopia por fibra ótica projetada para observação duodenal e canulação da AMPOLA DE VATER, para visualizar o sistema de ductos pancreático e biliar por injeção de um meio de contraste retrógrado. A papilotomia endoscópica (Vater) (ESFINCTEROTOMIA ENDOSCÓPICA) pode ser realizada durante este procedimento."},{"code":"D017081","term":"Colecistectomia Laparoscópica","name_en":"Cholecystectomy, Laparoscopic","tree_ids":["E04.210.120.172.140","E04.502.250.520.160"],"hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.210.120.172.140","branches":[{"tree_id":"E04.210.120.172.140","hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.210.120.172.140"},{"tree_id":"E04.502.250.520.160","hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.502.250.520.160"}],"search_method":"text","role":"primary","scope_note":"Excisão da vesícula biliar através de uma incisão utilizando um laparoscópio."},{"code":"D011184","term":"Período Pós-Operatório","name_en":"Postoperative Period","tree_ids":["E04.614.750","N02.421.585.753.750"],"hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.614.750","branches":[{"tree_id":"E04.614.750","hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.614.750"},{"tree_id":"N02.421.585.753.750","hierarchy_path":"Saúde › N02.421.585.753.750"}],"search_method":"text","role":"secondary","scope_note":"Período que se segue a uma operação cirúrgica."},{"code":"D002758","term":"Colangiografia","name_en":"Cholangiography","tree_ids":["E01.370.350.700.715.200","E01.370.372.200"],"hierarchy_path":"Técnicas e Equipamentos Analíticos › E01.370.350.700.715.200","branches":[{"tree_id":"E01.370.350.700.715.200","hierarchy_path":"Técnicas e Equipamentos Analíticos › E01.370.350.700.715.200"},{"tree_id":"E01.370.372.200","hierarchy_path":"Técnicas e Equipamentos Analíticos › E01.370.372.200"}],"search_method":"text","role":"secondary","scope_note":"Exame de imagem do TRATO BILIAR em que um corante de contraste (MEIO RADIOPACO) é injetado no DUCTO COLÉDOCO e são tiradas radiografias por raios X."},{"code":"D019736","term":"Próteses e Implantes","name_en":"Prostheses and Implants","tree_ids":["E07.695","VS2.006.002.010"],"hierarchy_path":"Técnicas e Equipamentos Analíticos › E07.695","branches":[{"tree_id":"E07.695","hierarchy_path":"Técnicas e Equipamentos Analíticos › E07.695"},{"tree_id":"VS2.006.002.010","hierarchy_path":"Vigilância Sanitária › VS2.006.002.010"}],"search_method":"text","role":"secondary","scope_note":"Substitutos artificiais para partes do corpo, e materiais inseridos em tecidos para propósitos funcionais, cosméticos ou terapêuticos. As próteses podem ser funcionais, como no caso de braços e pernas artificiais, ou cosméticas, como no caso de um olho artificial. Os implantes, todos cirurgicamente inseridos ou enxertados no corpo, tendem a ser utilizados terapeuticamente. IMPLANTES EXPERIMENTAIS estão disponíveis para aqueles usados experimentalmente."},{"code":"D000900","term":"Antibacterianos","name_en":"Anti-Bacterial Agents","tree_ids":["D27.505.954.122.085","SP4.606.635.823.796.135","VS2.002.001.012","VS2.004.001.002.006"],"hierarchy_path":"Compostos Químicos e Drogas › D27.505.954.122.085","branches":[{"tree_id":"D27.505.954.122.085","hierarchy_path":"Compostos Químicos e Drogas › D27.505.954.122.085"},{"tree_id":"SP4.606.635.823.796.135","hierarchy_path":"Saúde Pública › SP4.606.635.823.796.135"},{"tree_id":"VS2.002.001.012","hierarchy_path":"Vigilância Sanitária › VS2.002.001.012"},{"tree_id":"VS2.004.001.002.006","hierarchy_path":"Vigilância Sanitária › VS2.004.001.002.006"}],"search_method":"text","role":"secondary","scope_note":"Substâncias que inibem a proliferação ou a reprodução de BACTÉRIAS."}]', NULL, NULL, NULL, NULL, NULL, '{"competencias":[{"competencia":"Indicação de tratamento","conteudos":[],"id":"97","justificativa":"O candidato precisa identificar qual das opções de tratamento é a mais indicada para uma fístula biliar de baixo débito sem coleções, considerando a eficácia e a invasividade.","principal":false}],"novas_competencias":[]}', '{"temas":[{"tema":"Doenças das vias biliares","subtemas":["Lesões iatrogênicas das vias biliares"],"principal":true},{"tema":"Perioperatório","subtemas":["Complicações pós-operatórias e profilaxia de TEV"],"principal":false}],"tema_principal":"Doenças das vias biliares"}', '{"source":"backfill-missing-primary-meta","kept_count":7,"dismissed_at":null,"validated_at":"2026-07-30T18:11:45.078Z","primary_count":3,"removed_count":1,"review_reason":"Único termo candidato (''Depressão'') foi descartado por falta de equivalência semântica com qualquer conceito da questão, resultando em ausência de termos no conjunto final.","coerencia_geral":0,"needs_manual_review":false,"missing_primary_terms":false}'::jsonb, 25587, 560, '{"totals":{"by_agent":{"decs_classifier":{"calls":1,"input_tokens":1653,"total_tokens":2903,"output_tokens":66},"habilities_agent":{"calls":1,"input_tokens":8373,"total_tokens":8632,"output_tokens":259},"question_terms_validator":{"calls":1,"input_tokens":2719,"total_tokens":3603,"output_tokens":130},"question_themes_assigner":{"calls":1,"input_tokens":12842,"total_tokens":12947,"output_tokens":105}},"input_tokens":25587,"total_tokens":28085,"output_tokens":560,"thoughts_tokens":1938},"operations":[{"agent":"decs_classifier","model":"gemini-2.5-flash","input_tokens":1653,"total_tokens":2903,"output_tokens":66,"thoughts_tokens":1184},{"agent":"question_terms_validator","model":"gemini-2.5-flash","input_tokens":2719,"total_tokens":3603,"output_tokens":130,"thoughts_tokens":754},{"agent":"question_themes_assigner","model":"gemini-2.5-flash","input_tokens":12842,"total_tokens":12947,"output_tokens":105},{"agent":"habilities_agent","model":"gemini-2.5-flash","input_tokens":8373,"total_tokens":8632,"output_tokens":259}],"updated_at":"2026-07-30T18:11:48.667Z","estimated_cost_usd":{"input_usd":0.007676,"total_usd":0.009076,"output_usd":0.0014}}'::jsonb)
