INSERT INTO public.questions ("id", "statement", "option_a", "option_b", "option_c", "option_d", "option_e", "correct_answer", "explanation", "tags", "images", "exam_year", "exam_board", "exam_institution", "exam_region", "exam_type", "prova_id", "numero_na_prova", "areas_conhecimento", "assuntos", "created_at", "updated_at", "anulada", "decs_terms", "ai_decs_descriptors", "ai_decs_v2", "ai_decs_classified_text", "images_meta", "competencias", "temas", "ai_habilities", "ai_question_themes", "decs_validation_meta", "input_tokens", "output_tokens", "ai_token_usage")
VALUES (1702, 'Um paciente com histórico de cirurgia abdominal complexa apresenta uma fístula entérica de alto débito com drenagem cutânea significativa e sinais de desnutrição. Qual(is) é(são) o(s) manejo(s) inicial(is) mais adequado(s) para essa condição?', 'Correção cirúrgica imediata, com fechamento da fístula.', 'Jejum, suporte nutricional parenteral e controle de eletrólitos.', 'Antibioticoterapia de amplo espectro e drenagem percutânea.', 'Uso de dieta enteral para reduzir o débito da fístula.', NULL, 'B', NULL, NULL, '[]', 2025, 'ABC', NULL, 'SP', 'MASTOLOGIA', 20, 8, NULL, NULL, '2026-04-08T21:50:21.341404+00:00', '2026-08-06T18:52:01.536155+00:00', FALSE, NULL, '[{"code":"D007412","term":"Fístula Intestinal","name_en":"Intestinal Fistula","tree_ids":["C06.267.550","C06.405.469.471","C23.300.575.185.550"],"hierarchy_path":"Doenças › C06.267.550","branches":[{"tree_id":"C06.267.550","hierarchy_path":"Doenças › C06.267.550"},{"tree_id":"C06.405.469.471","hierarchy_path":"Doenças › C06.405.469.471"},{"tree_id":"C23.300.575.185.550","hierarchy_path":"Doenças › C23.300.575.185.550"}],"search_method":"text","role":"primary","scope_note":"Passagem anatômica anormal entre o INTESTINO e qualquer segmento do intestino ou outro órgão. A fístula intestinal externa está conectada à PELE (fístula enterocutânea). A fístula intestinal interna pode estar conectada a vários órgãos, como ESTÔMAGO (fístula gastrocólica), TRATO BILIAR (fístula colecistoduodenal) ou BEXIGA URINÁRIA do TRATO URINÁRIO (fístula colovesical). Entre os fatores de risco estão os processos inflamatórios, câncer, tratamento por radiação e acidentes cirúrgicos (ERROS MÉDICOS)."},{"code":"D010288","term":"Nutrição Parenteral","name_en":"Parenteral Nutrition","tree_ids":["E02.421.505","E02.642.500.505","VS3.003.001.006.005.002.002"],"hierarchy_path":"Técnicas e Equipamentos Analíticos › E02.421.505","branches":[{"tree_id":"E02.421.505","hierarchy_path":"Técnicas e Equipamentos Analíticos › E02.421.505"},{"tree_id":"E02.642.500.505","hierarchy_path":"Técnicas e Equipamentos Analíticos › E02.642.500.505"},{"tree_id":"VS3.003.001.006.005.002.002","hierarchy_path":"Vigilância Sanitária › VS3.003.001.006.005.002.002"}],"search_method":"text","role":"primary","scope_note":"Administração de nutrientes para assimilação e utilização por um paciente que não pode manter uma nutrição adequada somente pela alimentação enteral. Os nutrientes são administrados por uma via diferente daquela do canal alimentar (por exemplo, por via endovenosa, subcutânea)."},{"code":"D044342","term":"Desnutrição","name_en":"Malnutrition","tree_ids":["C18.654.521","SP6.990.625.344"],"hierarchy_path":"Doenças › C18.654.521","branches":[{"tree_id":"C18.654.521","hierarchy_path":"Doenças › C18.654.521"},{"tree_id":"SP6.990.625.344","hierarchy_path":"Saúde Pública › SP6.990.625.344"}],"search_method":"text","role":"primary","scope_note":"Estado de desequilíbrio nutricional, resultante de ingestão insuficiente de nutrientes para atender às necessidades fisiológicas normais."},{"code":"D005215","term":"Jejum","name_en":"Fasting","tree_ids":["F01.145.407.400","G07.203.650.240.587","G07.203.650.353.400"],"hierarchy_path":"Psiquiatria e Psicologia › F01.145.407.400","branches":[{"tree_id":"F01.145.407.400","hierarchy_path":"Psiquiatria e Psicologia › F01.145.407.400"},{"tree_id":"G07.203.650.240.587","hierarchy_path":"Fenômenos Biológicos › G07.203.650.240.587"},{"tree_id":"G07.203.650.353.400","hierarchy_path":"Fenômenos Biológicos › G07.203.650.353.400"}],"search_method":"text","role":"secondary","scope_note":"Abstenção de ALIMENTO."},{"code":"D004573","term":"Eletrólitos","name_en":"Electrolytes","tree_ids":["D01.248"],"hierarchy_path":"Compostos Químicos e Drogas › D01.248","branches":[{"tree_id":"D01.248","hierarchy_path":"Compostos Químicos e Drogas › D01.248"}],"search_method":"text","role":"secondary","scope_note":"Substâncias que se dissociam em dois ou mais íons, de certa maneira, em água. Assim, soluções de eletrólitos conduzem corrente elétrica e podem ser decompostas por ela (ELETRÓLISE)."},{"code":"D004750","term":"Nutrição Enteral","name_en":"Enteral Nutrition","tree_ids":["E02.421.360","E02.642.500.360","VS3.003.001.006.005.002.001"],"hierarchy_path":"Técnicas e Equipamentos Analíticos › E02.421.360","branches":[{"tree_id":"E02.421.360","hierarchy_path":"Técnicas e Equipamentos Analíticos › E02.421.360"},{"tree_id":"E02.642.500.360","hierarchy_path":"Técnicas e Equipamentos Analíticos › E02.642.500.360"},{"tree_id":"VS3.003.001.006.005.002.001","hierarchy_path":"Vigilância Sanitária › VS3.003.001.006.005.002.001"}],"search_method":"text","role":"secondary","scope_note":"Manutenção nutricional através do canal alimentar ou qualquer via conectada ao sistema gastrointestinal (isto é, a via enteral). Inclui alimentação oral, alimentação por gotas e alimentação por sondas nasogástricas, gastrostomia e jejunostomia."}]', NULL, NULL, NULL, NULL, NULL, '{"competencias":[{"competencia":"Terapia não farmacológica","conteudos":[],"id":"100","justificativa":"A resposta correta envolve medidas terapêuticas não medicamentosas como jejum e suporte nutricional parenteral, que são cruciais no manejo inicial da fístula.","principal":false},{"competencia":"Interpretação de eletrólitos","conteudos":[],"id":"80","justificativa":"O controle de eletrólitos é uma parte essencial do manejo inicial de pacientes com fístulas de alto débito, que perdem grandes volumes de fluidos e eletrólitos.","principal":false}],"novas_competencias":[]}', '{"temas":[{"tema":"Perioperatório","subtemas":["Nutrição e Projeto ACERTO","Complicações pós-operatórias e profilaxia de TEV"],"principal":true},{"tema":"Distúrbios hidroeletrolíticos","subtemas":["Distúrbios hidroeletrolíticos"],"principal":false},{"tema":"Desnutrição","subtemas":["Desnutrição"],"principal":false}],"tema_principal":"Perioperatório"}', '{"source":"backfill-missing-primary-meta","kept_count":6,"dismissed_at":null,"validated_at":"2026-07-30T18:13:03.019Z","primary_count":3,"removed_count":2,"review_reason":"Todos os termos candidatos fornecidos foram excluídos por incoerência com o contexto clínico da questão e o gabarito, resultando na ausência de termos primários e secundários no conjunto final.","coerencia_geral":7,"needs_manual_review":false,"missing_primary_terms":false}'::jsonb, 25644, 674, '{"totals":{"by_agent":{"decs_classifier":{"calls":1,"input_tokens":1640,"total_tokens":2938,"output_tokens":43},"habilities_agent":{"calls":1,"input_tokens":8360,"total_tokens":8696,"output_tokens":336},"question_terms_validator":{"calls":1,"input_tokens":2815,"total_tokens":5395,"output_tokens":154},"question_themes_assigner":{"calls":1,"input_tokens":12829,"total_tokens":12970,"output_tokens":141}},"input_tokens":25644,"total_tokens":29999,"output_tokens":674,"thoughts_tokens":3681},"operations":[{"agent":"decs_classifier","model":"gemini-2.5-flash","input_tokens":1640,"total_tokens":2938,"output_tokens":43,"thoughts_tokens":1255},{"agent":"question_terms_validator","model":"gemini-2.5-flash","input_tokens":2815,"total_tokens":5395,"output_tokens":154,"thoughts_tokens":2426},{"agent":"question_themes_assigner","model":"gemini-2.5-flash","input_tokens":12829,"total_tokens":12970,"output_tokens":141},{"agent":"habilities_agent","model":"gemini-2.5-flash","input_tokens":8360,"total_tokens":8696,"output_tokens":336}],"updated_at":"2026-07-30T18:13:06.595Z","estimated_cost_usd":{"input_usd":0.007693,"total_usd":0.009378,"output_usd":0.001685}}'::jsonb)
