VALUES (1703, 'Um paciente com colostomia terminal, para descompressão após ressecção de câncer de cólon, apresenta irritação cutânea periostomal e queixa de desconforto constante. Assinale a alternativa que apresenta a complicação mais comum associada a colostomias e que deve ser considerada nesse caso.', 'Prolapso da colostomia.', 'Retração da colostomia.', 'Dermatite periostomal.', 'Obstrução da colostomia.', NULL, 'C', NULL, NULL, '[]', 2025, 'ABC', NULL, 'SP', 'MASTOLOGIA', 20, 9, NULL, NULL, '2026-04-08T21:50:21.343523+00:00', '2026-08-06T18:52:01.536155+00:00', FALSE, NULL, '[{"code":"D003125","term":"Colostomia","name_en":"Colostomy","tree_ids":["E04.210.338.225","E04.579.338.225"],"hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.210.338.225","branches":[{"tree_id":"E04.210.338.225","hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.210.338.225"},{"tree_id":"E04.579.338.225","hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.579.338.225"}],"search_method":"text","role":"primary","scope_note":"Construção cirúrgica de uma abertura entre o cólon e a superfície do corpo."},{"code":"D003872","term":"Dermatite","name_en":"Dermatitis","tree_ids":["C17.800.174"],"hierarchy_path":"Doenças › C17.800.174","branches":[{"tree_id":"C17.800.174","hierarchy_path":"Doenças › C17.800.174"}],"search_method":"text","role":"primary","scope_note":"Qualquer inflamação da pele."},{"code":"D015179","term":"Neoplasias Colorretais","name_en":"Colorectal Neoplasms","tree_ids":["C04.588.274.476.411.307","C06.301.371.411.307","C06.405.249.411.307","C06.405.469.158.356","C06.405.469.491.307","C06.405.469.860.180"],"hierarchy_path":"Doenças › C04.588.274.476.411.307","branches":[{"tree_id":"C04.588.274.476.411.307","hierarchy_path":"Doenças › C04.588.274.476.411.307"},{"tree_id":"C06.301.371.411.307","hierarchy_path":"Doenças › C06.301.371.411.307"},{"tree_id":"C06.405.249.411.307","hierarchy_path":"Doenças › C06.405.249.411.307"},{"tree_id":"C06.405.469.158.356","hierarchy_path":"Doenças › C06.405.469.158.356"},{"tree_id":"C06.405.469.491.307","hierarchy_path":"Doenças › C06.405.469.491.307"},{"tree_id":"C06.405.469.860.180","hierarchy_path":"Doenças › C06.405.469.860.180"}],"search_method":"text","role":"secondary","scope_note":"Tumores ou câncer do cólon, ou do RETO ou ambos. Entre os fatores de risco para o câncer colorretal estão colite ulcerativa crônica, polipose familiar do cólon, exposição a ASBESTO e irradiação do COLO DO ÚTERO."}]', NULL, NULL, NULL, NULL, NULL, '{"competencias":[{"competencia":"Diagnóstico diferencial","conteudos":[],"id":"67","justificativa":"Embora a dermatite seja a mais comum, o candidato precisa considerar e descartar outras complicações da colostomia (prolapso, retração, obstrução) que são apresentadas como alternativas, exercitando o diagnóstico diferencial.","principal":false}],"novas_competencias":[]}', '{"temas":[{"tema":"Câncer colorretal","subtemas":["Câncer colorretal"],"principal":false},{"tema":"Doenças orificiais","subtemas":["Doenças orificiais"],"principal":true}],"tema_principal":"Doenças orificiais"}', '{"source":"backfill-missing-primary-meta","kept_count":3,"dismissed_at":null,"validated_at":"2026-07-30T18:13:41.086Z","primary_count":2,"removed_count":0,"review_reason":"Nenhum descritor vetorial/API disponível para validação (apenas textuais ou lista vazia).","coerencia_geral":0,"needs_manual_review":true,"missing_primary_terms":false}'::jsonb, 22745, 292, '{"totals":{"by_agent":{"decs_classifier":{"calls":1,"input_tokens":1612,"total_tokens":2620,"output_tokens":20},"habilities_agent":{"calls":1,"input_tokens":8332,"total_tokens":8526,"output_tokens":194},"question_themes_assigner":{"calls":1,"input_tokens":12801,"total_tokens":12879,"output_tokens":78}},"input_tokens":22745,"total_tokens":24025,"output_tokens":292,"thoughts_tokens":988},"operations":[{"agent":"decs_classifier","model":"gemini-2.5-flash","input_tokens":1612,"total_tokens":2620,"output_tokens":20,"thoughts_tokens":988},{"agent":"question_themes_assigner","model":"gemini-2.5-flash","input_tokens":12801,"total_tokens":12879,"output_tokens":78},{"agent":"habilities_agent","model":"gemini-2.5-flash","input_tokens":8332,"total_tokens":8526,"output_tokens":194}],"updated_at":"2026-07-30T18:13:44.739Z","estimated_cost_usd":{"input_usd":0.006824,"total_usd":0.007554,"output_usd":0.00073}}'::jsonb)
