INSERT INTO public.questions ("id", "statement", "option_a", "option_b", "option_c", "option_d", "option_e", "correct_answer", "explanation", "tags", "images", "exam_year", "exam_board", "exam_institution", "exam_region", "exam_type", "prova_id", "numero_na_prova", "areas_conhecimento", "assuntos", "created_at", "updated_at", "anulada", "decs_terms", "ai_decs_descriptors", "ai_decs_v2", "ai_decs_classified_text", "images_meta", "competencias", "temas", "ai_habilities", "ai_question_themes", "decs_validation_meta", "input_tokens", "output_tokens", "ai_token_usage")
VALUES (1704, 'Um homem, 40 anos, com doença de Crohn, apresenta fístula anorretal complexa com trajetos múltiplos. Qual das opções terapêuticas é mais indicada para tratar fístulas anorretais complexas em pacientes com doença de Crohn, preservando a função esfincteriana?', 'Fistulotomia com excisão ampla da fístula.', 'Colocação de seton para drenagem e controle da infecção.', 'Cirurgia de avanço do retalho mucoso.', 'Tratamento antibiótico prolongado.', NULL, 'B', NULL, NULL, '[]', 2025, 'ABC', NULL, 'SP', 'MASTOLOGIA', 20, 10, NULL, NULL, '2026-04-08T21:50:21.345753+00:00', '2026-08-06T18:52:01.536155+00:00', FALSE, NULL, '[{"code":"D003424","term":"Doença de Crohn","name_en":"Crohn Disease","tree_ids":["C06.405.205.731.500","C06.405.469.432.500"],"hierarchy_path":"Doenças › C06.405.205.731.500","branches":[{"tree_id":"C06.405.205.731.500","hierarchy_path":"Doenças › C06.405.205.731.500"},{"tree_id":"C06.405.469.432.500","hierarchy_path":"Doenças › C06.405.469.432.500"}],"search_method":"text","role":"primary","scope_note":"Inflamação transmural crônica que pode envolver qualquer parte do TRATO DIGESTÓRIO desde a BOCA até o ÂNUS, principalmente encontrada no ÍLEO, CECO, e COLO. Na doença de Crohn, a inflamação que se estende através da parede intestinal da MUCOSA até a serosa, é caracteristicamente assimétrica e segmentar. GRANULOMAS epitelioides podem ser vistos em alguns pacientes."},{"term":"Fístula Retal","code":"D012003","tree_ids":["C06.267.550.600","C06.405.469.471.600","C06.405.469.860.752","C23.300.575.185.550.600"],"hierarchy_path":"Doenças › C06.267.550.600","branches":[{"tree_id":"C06.267.550.600","hierarchy_path":"Doenças › C06.267.550.600"},{"tree_id":"C06.405.469.471.600","hierarchy_path":"Doenças › C06.405.469.471.600"},{"tree_id":"C06.405.469.860.752","hierarchy_path":"Doenças › C06.405.469.860.752"},{"tree_id":"C23.300.575.185.550.600","hierarchy_path":"Doenças › C23.300.575.185.550.600"}],"scope_note":"Passagem anatômica anormal conectando o RETO com o exterior, com um orifício no lugar da drenagem.","name_en":"Rectal Fistula","search_method":"vector","role":"primary"},{"term":"Retalhos Cirúrgicos","code":"D013524","tree_ids":["A10.850.710","E07.862.710"],"hierarchy_path":"Anatomia › A10.850.710","branches":[{"tree_id":"A10.850.710","hierarchy_path":"Anatomia › A10.850.710"},{"tree_id":"E07.862.710","hierarchy_path":"Técnicas e Equipamentos Analíticos › E07.862.710"}],"scope_note":"Pedaços de pele e tecido subcutâneo, às vezes incluindo músculos retirados de partes subjacentes, porém frequentemente ainda presas a uma extremidade. Eles retêm a própria microvasculatura que também é transferida para o novo local. São utilizados em cirurgias plásticas para reparar um defeito em região vizinha.","name_en":"Surgical Flaps","search_method":"vector","role":"secondary"},{"code":"D000900","term":"Antibacterianos","name_en":"Anti-Bacterial Agents","tree_ids":["D27.505.954.122.085","SP4.606.635.823.796.135","VS2.002.001.012","VS2.004.001.002.006"],"hierarchy_path":"Compostos Químicos e Drogas › D27.505.954.122.085","branches":[{"tree_id":"D27.505.954.122.085","hierarchy_path":"Compostos Químicos e Drogas › D27.505.954.122.085"},{"tree_id":"SP4.606.635.823.796.135","hierarchy_path":"Saúde Pública › SP4.606.635.823.796.135"},{"tree_id":"VS2.002.001.012","hierarchy_path":"Vigilância Sanitária › VS2.002.001.012"},{"tree_id":"VS2.004.001.002.006","hierarchy_path":"Vigilância Sanitária › VS2.004.001.002.006"}],"search_method":"text","role":"secondary","scope_note":"Substâncias que inibem a proliferação ou a reprodução de BACTÉRIAS."}]', NULL, NULL, NULL, NULL, NULL, NULL, '{"temas":[{"tema":"Doenças inflamatórias intestinais","subtemas":["Doenças inflamatórias intestinais"],"principal":true},{"tema":"Doenças orificiais","subtemas":["Fístula perianal"],"principal":false}],"tema_principal":"Doenças inflamatórias intestinais"}', '{"source":"backfill-missing-primary-meta","kept_count":4,"dismissed_at":null,"validated_at":"2026-07-30T18:14:35.331Z","primary_count":2,"removed_count":2,"review_reason":"Termos primários essenciais como ''Doença de Crohn'' (entidade principal) e ''Setons'' (tratamento correto) não foram encontrados ou aprovados, resultando em uma representação incompleta do caso clínico e da resposta. O conjunto final de termos aprovados não captura a totalidade do conceito central da questão.","coerencia_geral":49,"needs_manual_review":false,"missing_primary_terms":false}'::jsonb, 25804, 739, '{"totals":{"by_agent":{"decs_classifier":{"calls":1,"input_tokens":1628,"total_tokens":2886,"output_tokens":37},"habilities_agent":{"calls":1,"input_tokens":8348,"total_tokens":8613,"output_tokens":265},"question_terms_validator":{"calls":1,"input_tokens":3011,"total_tokens":5824,"output_tokens":345},"question_themes_assigner":{"calls":1,"input_tokens":12817,"total_tokens":12909,"output_tokens":92}},"input_tokens":25804,"total_tokens":30232,"output_tokens":739,"thoughts_tokens":3689},"operations":[{"agent":"decs_classifier","model":"gemini-2.5-flash","input_tokens":1628,"total_tokens":2886,"output_tokens":37,"thoughts_tokens":1221},{"agent":"question_terms_validator","model":"gemini-2.5-flash","input_tokens":3011,"total_tokens":5824,"output_tokens":345,"thoughts_tokens":2468},{"agent":"question_themes_assigner","model":"gemini-2.5-flash","input_tokens":12817,"total_tokens":12909,"output_tokens":92},{"agent":"habilities_agent","model":"gemini-2.5-flash","input_tokens":8348,"total_tokens":8613,"output_tokens":265}],"updated_at":"2026-07-30T18:14:39.486Z","estimated_cost_usd":{"input_usd":0.007741,"total_usd":0.009589,"output_usd":0.001848}}'::jsonb)
