INSERT INTO public.questions ("id", "statement", "option_a", "option_b", "option_c", "option_d", "option_e", "correct_answer", "explanation", "tags", "images", "exam_year", "exam_board", "exam_institution", "exam_region", "exam_type", "prova_id", "numero_na_prova", "areas_conhecimento", "assuntos", "created_at", "updated_at", "anulada", "decs_terms", "ai_decs_descriptors", "ai_decs_v2", "ai_decs_classified_text", "images_meta", "competencias", "temas", "ai_habilities", "ai_question_themes", "decs_validation_meta", "input_tokens", "output_tokens", "ai_token_usage")
VALUES (1705, 'Em um paciente crítico, a escolha entre dieta enteral e parenteral deve ser cuidadosa. Em relação às vantagens e desvantagens das dietas parenteral e enteral, assinale a alternativa correta.', 'A dieta parenteral possui menor custo, reduz o risco de infecções e é mais fácil de administrar, mas pode aumentar o risco de infecções de corrente sanguínea.', 'A dieta enteral melhora a integridade da mucosa gastrointestinal e é mais fisiológica, mas pode ser inadequada em pacientes com absorção intestinal comprometida', 'A dieta enteral proporciona maior controle de eletrólitos, porém é contraindicada em pacientes críticos e instáveis.', 'A dieta parenteral tem custo mais elevado, mas menor risco de infecções e complicações metabólicas.', NULL, 'B', NULL, NULL, '[]', 2025, 'ABC', NULL, 'SP', 'MASTOLOGIA', 20, 11, NULL, NULL, '2026-04-08T21:50:21.348524+00:00', '2026-08-06T18:52:01.536155+00:00', FALSE, NULL, '[{"code":"D004750","term":"Nutrição Enteral","name_en":"Enteral Nutrition","tree_ids":["E02.421.360","E02.642.500.360","VS3.003.001.006.005.002.001"],"hierarchy_path":"Técnicas e Equipamentos Analíticos › E02.421.360","branches":[{"tree_id":"E02.421.360","hierarchy_path":"Técnicas e Equipamentos Analíticos › E02.421.360"},{"tree_id":"E02.642.500.360","hierarchy_path":"Técnicas e Equipamentos Analíticos › E02.642.500.360"},{"tree_id":"VS3.003.001.006.005.002.001","hierarchy_path":"Vigilância Sanitária › VS3.003.001.006.005.002.001"}],"search_method":"text","role":"primary","scope_note":"Manutenção nutricional através do canal alimentar ou qualquer via conectada ao sistema gastrointestinal (isto é, a via enteral). Inclui alimentação oral, alimentação por gotas e alimentação por sondas nasogástricas, gastrostomia e jejunostomia."},{"code":"D010288","term":"Nutrição Parenteral","name_en":"Parenteral Nutrition","tree_ids":["E02.421.505","E02.642.500.505","VS3.003.001.006.005.002.002"],"hierarchy_path":"Técnicas e Equipamentos Analíticos › E02.421.505","branches":[{"tree_id":"E02.421.505","hierarchy_path":"Técnicas e Equipamentos Analíticos › E02.421.505"},{"tree_id":"E02.642.500.505","hierarchy_path":"Técnicas e Equipamentos Analíticos › E02.642.500.505"},{"tree_id":"VS3.003.001.006.005.002.002","hierarchy_path":"Vigilância Sanitária › VS3.003.001.006.005.002.002"}],"search_method":"text","role":"primary","scope_note":"Administração de nutrientes para assimilação e utilização por um paciente que não pode manter uma nutrição adequada somente pela alimentação enteral. Os nutrientes são administrados por uma via diferente daquela do canal alimentar (por exemplo, por via endovenosa, subcutânea)."},{"term":"Cuidados Críticos","code":"D003422","tree_ids":["E02.760.190","N02.421.585.190"],"hierarchy_path":"Técnicas e Equipamentos Analíticos › E02.760.190","branches":[{"tree_id":"E02.760.190","hierarchy_path":"Técnicas e Equipamentos Analíticos › E02.760.190"},{"tree_id":"N02.421.585.190","hierarchy_path":"Saúde › N02.421.585.190"}],"scope_note":"Tratamento de saúde prestado a pacientes em estado crítico.","name_en":"Critical Care","search_method":"vector","role":"primary"},{"code":"D007413","term":"Mucosa Intestinal","name_en":"Intestinal Mucosa","tree_ids":["A03.556.124.369","A10.615.550.444"],"hierarchy_path":"Anatomia › A03.556.124.369","branches":[{"tree_id":"A03.556.124.369","hierarchy_path":"Anatomia › A03.556.124.369"},{"tree_id":"A10.615.550.444","hierarchy_path":"Anatomia › A10.615.550.444"}],"search_method":"text","role":"secondary","scope_note":"Revestimento dos INTESTINOS, consistindo em um EPITÉLIO interior, uma LÂMINA PRÓPRIA média, e uma MUSCULARIS MUCOSAE exterior. No INTESTINO DELGADO, a mucosa é caracterizada por várias dobras e muitas células absortivas (ENTERÓCITOS) com MICROVILOSIDADES."},{"code":"D007408","term":"Absorção Intestinal","name_en":"Intestinal Absorption","tree_ids":["G03.015.500.374.500","G03.787.024.500.374.500","G07.203.650.372.500","G07.690.725.015.500.374.500","G10.261.353.500"],"hierarchy_path":"Fenômenos Biológicos › G03.015.500.374.500","branches":[{"tree_id":"G03.015.500.374.500","hierarchy_path":"Fenômenos Biológicos › G03.015.500.374.500"},{"tree_id":"G03.787.024.500.374.500","hierarchy_path":"Fenômenos Biológicos › G03.787.024.500.374.500"},{"tree_id":"G07.203.650.372.500","hierarchy_path":"Fenômenos Biológicos › G07.203.650.372.500"},{"tree_id":"G07.690.725.015.500.374.500","hierarchy_path":"Fenômenos Biológicos › G07.690.725.015.500.374.500"},{"tree_id":"G10.261.353.500","hierarchy_path":"Fenômenos Biológicos › G10.261.353.500"}],"search_method":"text","role":"secondary","scope_note":"Captação de substâncias através do revestimento interno dos INTESTINOS."},{"code":"D007239","term":"Infecções","name_en":"Infections","tree_ids":["C01"],"hierarchy_path":"Doenças","branches":[{"tree_id":"C01","hierarchy_path":"Doenças"}],"search_method":"text","role":"secondary","scope_note":"Invasão do organismo hospedeiro por microrganismos ou suas toxinas ou por parasitas que podem causar afecções patológicas ou doenças."},{"code":"D004573","term":"Eletrólitos","name_en":"Electrolytes","tree_ids":["D01.248"],"hierarchy_path":"Compostos Químicos e Drogas › D01.248","branches":[{"tree_id":"D01.248","hierarchy_path":"Compostos Químicos e Drogas › D01.248"}],"search_method":"text","role":"secondary","scope_note":"Substâncias que se dissociam em dois ou mais íons, de certa maneira, em água. Assim, soluções de eletrólitos conduzem corrente elétrica e podem ser decompostas por ela (ELETRÓLISE)."}]', NULL, NULL, NULL, NULL, NULL, '{"competencias":[{"competencia":"Terapia não farmacológica","conteudos":[],"id":"100","justificativa":"A questão compara as vantagens e desvantagens da dieta enteral e parenteral, que são formas de terapia nutricional não farmacológica em pacientes críticos.","principal":true}],"novas_competencias":[]}', '{"temas":[{"tema":"Perioperatório","subtemas":["Nutrição e Projeto ACERTO"],"principal":true},{"tema":"Desnutrição","subtemas":["Desnutrição"],"principal":false}],"tema_principal":"Perioperatório"}', '{"source":"backfill-missing-primary-meta","kept_count":7,"dismissed_at":null,"validated_at":"2026-07-30T18:15:20.070Z","primary_count":3,"removed_count":1,"review_reason":null,"coerencia_geral":64,"needs_manual_review":false,"missing_primary_terms":false}'::jsonb, 25738, 491, '{"totals":{"by_agent":{"decs_classifier":{"calls":1,"input_tokens":1667,"total_tokens":2686,"output_tokens":46},"habilities_agent":{"calls":1,"input_tokens":8387,"total_tokens":8562,"output_tokens":175},"question_terms_validator":{"calls":1,"input_tokens":2828,"total_tokens":5244,"output_tokens":189},"question_themes_assigner":{"calls":1,"input_tokens":12856,"total_tokens":12937,"output_tokens":81}},"input_tokens":25738,"total_tokens":29429,"output_tokens":491,"thoughts_tokens":3200},"operations":[{"agent":"decs_classifier","model":"gemini-2.5-flash","input_tokens":1667,"total_tokens":2686,"output_tokens":46,"thoughts_tokens":973},{"agent":"question_terms_validator","model":"gemini-2.5-flash","input_tokens":2828,"total_tokens":5244,"output_tokens":189,"thoughts_tokens":2227},{"agent":"question_themes_assigner","model":"gemini-2.5-flash","input_tokens":12856,"total_tokens":12937,"output_tokens":81},{"agent":"habilities_agent","model":"gemini-2.5-flash","input_tokens":8387,"total_tokens":8562,"output_tokens":175}],"updated_at":"2026-07-30T18:15:22.656Z","estimated_cost_usd":{"input_usd":0.007721,"total_usd":0.008949,"output_usd":0.001228}}'::jsonb)
