INSERT INTO public.questions ("id", "statement", "option_a", "option_b", "option_c", "option_d", "option_e", "correct_answer", "explanation", "tags", "images", "exam_year", "exam_board", "exam_institution", "exam_region", "exam_type", "prova_id", "numero_na_prova", "areas_conhecimento", "assuntos", "created_at", "updated_at", "anulada", "decs_terms", "ai_decs_descriptors", "ai_decs_v2", "ai_decs_classified_text", "images_meta", "competencias", "temas", "ai_habilities", "ai_question_themes", "decs_validation_meta", "input_tokens", "output_tokens", "ai_token_usage")
VALUES (1706, 'Durante uma cirurgia para resseção de câncer de cólon, é necessário liberar as estruturas adjacentes ao cólon e ao duodeno para mobilizar o intestino. Quais manobras cirúrgicas são usadas para a liberação dos cólons esquerdo e direito e do duodeno?', 'Manobra de Kocher para o cólon direito; manobra de Mattox para o cólon esquerdo; e manobra de Cattell para o duodeno.', 'Manobra de Mattox para o cólon esquerdo; manobra de Cattell para o cólon direito; e manobra de Kocher para o duodeno.', 'Manobra de Cattell para o cólon direito; manobra de Krocher para o cólon esquerdo; e manobra de Mattox para o duodeno.', 'Manobra de Cattell para o cólon esquerdo; manobra de Kocher para o cólon direito; e manobra de Mattox para o duodeno.', NULL, 'B', NULL, NULL, '[]', 2025, 'ABC', NULL, 'SP', 'MASTOLOGIA', 20, 12, NULL, NULL, '2026-04-08T21:50:21.350811+00:00', '2026-08-06T18:52:01.536155+00:00', FALSE, NULL, '[{"code":"D003082","term":"Colectomia","name_en":"Colectomy","tree_ids":["E04.210.896.001"],"hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.210.896.001","branches":[{"tree_id":"E04.210.896.001","hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.210.896.001"}],"search_method":"text","role":"primary","scope_note":"Ressecção cirúrgica de uma parte do cólon ou de todo o CÓLON."},{"code":"D003106","term":"Colo","name_en":"Colon","tree_ids":["A03.556.124.526.356","A03.556.249.249.356"],"hierarchy_path":"Anatomia › A03.556.124.526.356","branches":[{"tree_id":"A03.556.124.526.356","hierarchy_path":"Anatomia › A03.556.124.526.356"},{"tree_id":"A03.556.249.249.356","hierarchy_path":"Anatomia › A03.556.249.249.356"}],"search_method":"text","role":"primary","scope_note":"O segmento do INTESTINO GROSSO entre o CECO e o RETO. Inclui o COLO ASCENDENTE; o COLO TRANSVERSO; o COLO DESCENDENTE e o COLO SIGMOIDE."},{"code":"D004386","term":"Duodeno","name_en":"Duodenum","tree_ids":["A03.556.124.684.124","A03.556.875.249"],"hierarchy_path":"Anatomia › A03.556.124.684.124","branches":[{"tree_id":"A03.556.124.684.124","hierarchy_path":"Anatomia › A03.556.124.684.124"},{"tree_id":"A03.556.875.249","hierarchy_path":"Anatomia › A03.556.875.249"}],"search_method":"text","role":"primary","scope_note":"É a menor porção (e a mais larga) do INTESTINO DELGADO, adjacente ao PILORO do ESTÔMAGO. Seu nome é devido ao fato de seu comprimento ser igual à largura aproximada de 12 dedos."},{"code":"D015179","term":"Neoplasias Colorretais","name_en":"Colorectal Neoplasms","tree_ids":["C04.588.274.476.411.307","C06.301.371.411.307","C06.405.249.411.307","C06.405.469.158.356","C06.405.469.491.307","C06.405.469.860.180"],"hierarchy_path":"Doenças › C04.588.274.476.411.307","branches":[{"tree_id":"C04.588.274.476.411.307","hierarchy_path":"Doenças › C04.588.274.476.411.307"},{"tree_id":"C06.301.371.411.307","hierarchy_path":"Doenças › C06.301.371.411.307"},{"tree_id":"C06.405.249.411.307","hierarchy_path":"Doenças › C06.405.249.411.307"},{"tree_id":"C06.405.469.158.356","hierarchy_path":"Doenças › C06.405.469.158.356"},{"tree_id":"C06.405.469.491.307","hierarchy_path":"Doenças › C06.405.469.491.307"},{"tree_id":"C06.405.469.860.180","hierarchy_path":"Doenças › C06.405.469.860.180"}],"search_method":"text","role":"secondary","scope_note":"Tumores ou câncer do cólon, ou do RETO ou ambos. Entre os fatores de risco para o câncer colorretal estão colite ulcerativa crônica, polipose familiar do cólon, exposição a ASBESTO e irradiação do COLO DO ÚTERO."}]', NULL, NULL, NULL, NULL, NULL, NULL, '{"temas":[{"tema":"Técnica cirúrgica e instrumental","subtemas":["Técnica cirúrgica e instrumental"],"principal":true},{"tema":"Câncer colorretal","subtemas":["Câncer colorretal"],"principal":false}],"tema_principal":"Técnica cirúrgica e instrumental"}', '{"source":"backfill-missing-primary-meta","kept_count":4,"dismissed_at":null,"validated_at":"2026-07-30T18:15:45.871Z","primary_count":3,"removed_count":0,"review_reason":"Nenhum descritor vetorial/API disponível para validação (apenas textuais ou lista vazia).","coerencia_geral":0,"needs_manual_review":true,"missing_primary_terms":false}'::jsonb, 23072, 317, '{"totals":{"by_agent":{"decs_classifier":{"calls":1,"input_tokens":1721,"total_tokens":3288,"output_tokens":23},"habilities_agent":{"calls":1,"input_tokens":8441,"total_tokens":8654,"output_tokens":213},"question_themes_assigner":{"calls":1,"input_tokens":12910,"total_tokens":12991,"output_tokens":81}},"input_tokens":23072,"total_tokens":24933,"output_tokens":317,"thoughts_tokens":1544},"operations":[{"agent":"decs_classifier","model":"gemini-2.5-flash","input_tokens":1721,"total_tokens":3288,"output_tokens":23,"thoughts_tokens":1544},{"agent":"question_themes_assigner","model":"gemini-2.5-flash","input_tokens":12910,"total_tokens":12991,"output_tokens":81},{"agent":"habilities_agent","model":"gemini-2.5-flash","input_tokens":8441,"total_tokens":8654,"output_tokens":213}],"updated_at":"2026-07-30T18:15:48.241Z","estimated_cost_usd":{"input_usd":0.006922,"total_usd":0.007714,"output_usd":0.000793}}'::jsonb)
