INSERT INTO public.questions ("id", "statement", "option_a", "option_b", "option_c", "option_d", "option_e", "correct_answer", "explanation", "tags", "images", "exam_year", "exam_board", "exam_institution", "exam_region", "exam_type", "prova_id", "numero_na_prova", "areas_conhecimento", "assuntos", "created_at", "updated_at", "anulada", "decs_terms", "ai_decs_descriptors", "ai_decs_v2", "ai_decs_classified_text", "images_meta", "competencias", "temas", "ai_habilities", "ai_question_themes", "decs_validation_meta", "input_tokens", "output_tokens", "ai_token_usage")
VALUES (1707, 'Durante a consulta para correção de uma hérnia incisional, um paciente com histórico de infecção abdominal questiona o uso de telas para reforço da parede abdominal. Em relação aos tipos de telas, indicações e contraindicações, assinale a alternativa correta.', 'Telas de polipropileno são ideais para uso intraperitoneal em pacientes com risco de infecção, pois têm baixo potencial de aderência a tecidos viscerais.', 'Telas de polipropileno são indicadas para hérnias inguinais e incisões limpas, mas são contraindicadas em casos de contaminação ou risco elevado de infecção.', 'Telas de PTFE (politetrafluoretileno) são absorvíveis e, por isso, preferidas em casos de hérnias com contaminação, pois não permanecem no local.', 'Telas biológicas têm maior durabilidade e são recomendadas principalmente para cirurgias eletivas, pois apresentam baixo custo.', NULL, 'B', NULL, NULL, '[]', 2025, 'ABC', NULL, 'SP', 'MASTOLOGIA', 20, 13, NULL, NULL, '2026-04-08T21:50:21.352942+00:00', '2026-08-06T18:52:01.536155+00:00', FALSE, NULL, '[{"code":"D000069290","term":"Hérnia Incisional","name_en":"Incisional Hernia","tree_ids":["C23.300.707.945","C23.550.767.500"],"hierarchy_path":"Doenças › C23.300.707.945","branches":[{"tree_id":"C23.300.707.945","hierarchy_path":"Doenças › C23.300.707.945"},{"tree_id":"C23.550.767.500","hierarchy_path":"Doenças › C23.550.767.500"}],"search_method":"text","role":"primary","scope_note":"Protrusão de tecidos ou próximo ao local da incisão de uma cirurgia prévia."},{"code":"D013526","term":"Telas Cirúrgicas","name_en":"Surgical Mesh","tree_ids":["E07.858.708"],"hierarchy_path":"Técnicas e Equipamentos Analíticos › E07.858.708","branches":[{"tree_id":"E07.858.708","hierarchy_path":"Técnicas e Equipamentos Analíticos › E07.858.708"}],"search_method":"text","role":"primary","scope_note":"Qualquer material tecido ou tricotado de textura aberta usado em cirurgia para reparo, reconstituição ou substituição de tecido. A tela é usualmente um tecido sintético feito de vários polímeros. É ocasionalmente feita de metal."},{"term":"Polipropilenos","code":"D011126","tree_ids":["D02.455.326.271.665.590","D05.750.716.550","D25.720.716.550","J01.637.051.720.716.550"],"hierarchy_path":"Compostos Químicos e Drogas › D02.455.326.271.665.590","branches":[{"tree_id":"D02.455.326.271.665.590","hierarchy_path":"Compostos Químicos e Drogas › D02.455.326.271.665.590"},{"tree_id":"D05.750.716.550","hierarchy_path":"Compostos Químicos e Drogas › D05.750.716.550"},{"tree_id":"D25.720.716.550","hierarchy_path":"Compostos Químicos e Drogas › D25.720.716.550"},{"tree_id":"J01.637.051.720.716.550","hierarchy_path":"Tecnologia, Indústria, Agricultura › J01.637.051.720.716.550"}],"scope_note":"Polímeros de propileno ou propeno. Termoplásticos que podem ser prensados em fibras, filmes ou formas sólidas. São utilizados como copolímeros em plásticos, especialmente o polietileno. As fibras são utilizadas em tecidos, filtros e suturas cirúrgicas.","name_en":"Polypropylenes","search_method":"vector","role":"primary"},{"code":"D007239","term":"Infecções","name_en":"Infections","tree_ids":["C01"],"hierarchy_path":"Doenças","branches":[{"tree_id":"C01","hierarchy_path":"Doenças"}],"search_method":"text","role":"secondary","scope_note":"Invasão do organismo hospedeiro por microrganismos ou suas toxinas ou por parasitas que podem causar afecções patológicas ou doenças."},{"code":"D006552","term":"Hérnia Inguinal","name_en":"Hernia, Inguinal","tree_ids":["C23.300.707.374.875"],"hierarchy_path":"Doenças › C23.300.707.374.875","branches":[{"tree_id":"C23.300.707.374.875","hierarchy_path":"Doenças › C23.300.707.374.875"}],"search_method":"text","role":"secondary","scope_note":"Hérnia abdominal com uma saliência externa na região da VIRILHA. Pode ser classificada de acordo com a localização da herniação. As hérnias inguinais indiretas ocorrem através do anel inguinal interno. As hérnias inguinais diretas ocorrem através de defeitos na PAREDE ABDOMINAL (fáscia transversal) no triângulo de Hesselbach. O primeiro tipo, normalmente é observado em crianças e adultos jovens, o segundo em adultos."},{"term":"Politetrafluoretileno","code":"D011138","tree_ids":["D05.750.395.616","D25.720.395.616","J01.637.051.720.395.616"],"hierarchy_path":"Compostos Químicos e Drogas › D05.750.395.616","branches":[{"tree_id":"D05.750.395.616","hierarchy_path":"Compostos Químicos e Drogas › D05.750.395.616"},{"tree_id":"D25.720.395.616","hierarchy_path":"Compostos Químicos e Drogas › D25.720.395.616"},{"tree_id":"J01.637.051.720.395.616","hierarchy_path":"Tecnologia, Indústria, Agricultura › J01.637.051.720.395.616"}],"scope_note":"Homopolímero de tetrafluoretileno. Tubos ou fitas de plástico inerte, não inflamáveis, rígidos; usados para revestir recipientes, isolar, proteger e lubrificar equipamentos; também usados como membranas filtrantes, revestimento de implantes cirúrgicos, ou como material protético. Sinônimos: Fluoroflex; Fluoroplast; Ftoroplast; Halon; Polifeno; PTFE; Tetron.","name_en":"Polytetrafluoroethylene","search_method":"vector","role":"secondary"}]', NULL, NULL, NULL, NULL, NULL, '{"competencias":[{"competencia":"Contraindicações","conteudos":[],"id":"109","justificativa":"A alternativa correta e as incorretas discutem explicitamente as contraindicações de diferentes tipos de telas em cenários específicos, como risco de infecção ou contaminação.","principal":false}],"novas_competencias":[]}', '{"temas":[{"tema":"Hérnias","subtemas":["Outras hérnias"],"principal":true},{"tema":"Perioperatório","subtemas":["Antibiótico e infecção de sítio cirúrgico"],"principal":false}],"tema_principal":"Hérnias"}', '{"source":"backfill-missing-primary-meta","kept_count":6,"dismissed_at":null,"validated_at":"2026-07-30T18:16:43.441Z","primary_count":3,"removed_count":1,"review_reason":null,"coerencia_geral":69,"needs_manual_review":false,"missing_primary_terms":false}'::jsonb, 26072, 638, '{"totals":{"by_agent":{"decs_classifier":{"calls":1,"input_tokens":1711,"total_tokens":2480,"output_tokens":43},"habilities_agent":{"calls":1,"input_tokens":8431,"total_tokens":8682,"output_tokens":251},"question_terms_validator":{"calls":1,"input_tokens":3030,"total_tokens":4741,"output_tokens":241},"question_themes_assigner":{"calls":1,"input_tokens":12900,"total_tokens":13003,"output_tokens":103}},"input_tokens":26072,"total_tokens":28906,"output_tokens":638,"thoughts_tokens":2196},"operations":[{"agent":"decs_classifier","model":"gemini-2.5-flash","input_tokens":1711,"total_tokens":2480,"output_tokens":43,"thoughts_tokens":726},{"agent":"question_terms_validator","model":"gemini-2.5-flash","input_tokens":3030,"total_tokens":4741,"output_tokens":241,"thoughts_tokens":1470},{"agent":"question_themes_assigner","model":"gemini-2.5-flash","input_tokens":12900,"total_tokens":13003,"output_tokens":103},{"agent":"habilities_agent","model":"gemini-2.5-flash","input_tokens":8431,"total_tokens":8682,"output_tokens":251}],"updated_at":"2026-07-30T18:16:47.266Z","estimated_cost_usd":{"input_usd":0.007822,"total_usd":0.009417,"output_usd":0.001595}}'::jsonb)
