INSERT INTO public.questions ("id", "statement", "option_a", "option_b", "option_c", "option_d", "option_e", "correct_answer", "explanation", "tags", "images", "exam_year", "exam_board", "exam_institution", "exam_region", "exam_type", "prova_id", "numero_na_prova", "areas_conhecimento", "assuntos", "created_at", "updated_at", "anulada", "decs_terms", "ai_decs_descriptors", "ai_decs_v2", "ai_decs_classified_text", "images_meta", "competencias", "temas", "ai_habilities", "ai_question_themes", "decs_validation_meta", "input_tokens", "output_tokens", "ai_token_usage")
VALUES (1708, 'Durante uma cirurgia de emergência por perfuração gastrica, em um paciente com histórico de úlcera péptica, é realizada uma laparotomia exploradora. No intraoperatório, identifica-se uma perfuração no antro gástrico. Assinale a alternativa que apresenta a conduta mais indicada para o fechamento da perfuração nesse contexto.', 'Sutura simples, com pontos em U.', 'Sutura em camadas, com reforço de epíplon (operação de Graham).', 'Gastrectomia subtotal, com anastomose gastrojejunal.', 'Gastrojejunostomia, sem ressecção gástrica.', NULL, 'B', NULL, NULL, '[]', 2025, 'ABC', NULL, 'SP', 'MASTOLOGIA', 20, 14, NULL, NULL, '2026-04-08T21:50:21.35528+00:00', '2026-08-06T18:52:01.536155+00:00', FALSE, NULL, '[{"code":"D010437","term":"Úlcera Péptica","name_en":"Peptic Ulcer","tree_ids":["C06.405.469.275.800","C06.405.748.586"],"hierarchy_path":"Doenças › C06.405.469.275.800","branches":[{"tree_id":"C06.405.469.275.800","hierarchy_path":"Doenças › C06.405.469.275.800"},{"tree_id":"C06.405.748.586","hierarchy_path":"Doenças › C06.405.748.586"}],"search_method":"text","role":"primary","scope_note":"Úlcera que ocorre nas porções do TRATO GASTROINTESTINAL que entram em contato com o SUCO GÁSTRICO contendo PEPSINA e ÁCIDO GÁSTRICO. Ocorre quando há defeitos na barreira da MUCOSA. As formas comuns de úlcera péptica estão associadas com HELICOBACTER PYLORI e o consumo de drogas anti-inflamatórias não esteroides (NSAIDs)."},{"code":"D013537","term":"Suturas","name_en":"Sutures","tree_ids":["E07.858.690.820"],"hierarchy_path":"Técnicas e Equipamentos Analíticos › E07.858.690.820","branches":[{"tree_id":"E07.858.690.820","hierarchy_path":"Técnicas e Equipamentos Analíticos › E07.858.690.820"}],"search_method":"text","role":"primary","scope_note":"Materiais usados no fechamento de uma ferida cirúrgica ou traumática com pontos. (Dorland, 28a ed)"},{"code":"D007813","term":"Laparotomia","name_en":"Laparotomy","tree_ids":["E04.406"],"hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.406","branches":[{"tree_id":"E04.406","hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.406"}],"search_method":"text","role":"secondary","scope_note":"Incisão lateral no abdome entre as costelas e a pelve."},{"code":"D009852","term":"Omento","name_en":"Omentum","tree_ids":["A01.923.047.025.600.573"],"hierarchy_path":"Anatomia › A01.923.047.025.600.573","branches":[{"tree_id":"A01.923.047.025.600.573","hierarchy_path":"Anatomia › A01.923.047.025.600.573"}],"search_method":"text","role":"secondary","scope_note":"Dobra formada por duas camadas do peritônio que une o ESTÔMAGO a outros órgãos na CAVIDADE ABDOMINAL."},{"code":"D005743","term":"Gastrectomia","name_en":"Gastrectomy","tree_ids":["E04.210.419"],"hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.210.419","branches":[{"tree_id":"E04.210.419","hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.210.419"}],"search_method":"text","role":"secondary","scope_note":"Excisão de todo (g. total) ou parte (g. subtotal, g. parcial, ressecção gástrica) do estômago. (Dorland, 28a ed)"},{"term":"Gastroenterostomia","code":"D005763","tree_ids":["E04.035.398","E04.210.457"],"hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.035.398","branches":[{"tree_id":"E04.035.398","hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.035.398"},{"tree_id":"E04.210.457","hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.210.457"}],"scope_note":"Variedade dos procedimentos cirúrgicos reconstrutivos planejados para restaurar a continuidade gastrointestinal. As duas principais classes de procedimentos de reconstrução são a Billroth I (gastroduodenostomia) e a Billroth II (gastrojejunostomia).","name_en":"Gastroenterostomy","search_method":"vector","role":"secondary"},{"code":"D013270","term":"Estômago","name_en":"Stomach","tree_ids":["A03.556.875.875"],"hierarchy_path":"Anatomia › A03.556.875.875","branches":[{"tree_id":"A03.556.875.875","hierarchy_path":"Anatomia › A03.556.875.875"}],"search_method":"text","role":"secondary","scope_note":"Órgão da digestão, localizado no quadrante superior esquerdo do abdome, entre o final do ESÔFAGO e o início do DUODENO."}]', NULL, NULL, NULL, NULL, NULL, '{"competencias":[{"competencia":"Manejo de emergência","conteudos":[],"id":"116","justificativa":"A cirurgia é de emergência por perfuração gástrica, exigindo que o candidato considere o contexto de urgência na escolha da conduta.","principal":false}],"novas_competencias":[]}', '{"temas":[{"tema":"Abdome agudo","subtemas":["Abdome agudo perfurativo"],"principal":true},{"tema":"Perioperatório","subtemas":["Complicações pós-operatórias e profilaxia de TEV"],"principal":false}],"tema_principal":"Abdome agudo"}', '{"source":"backfill-missing-primary-meta","kept_count":7,"dismissed_at":null,"validated_at":"2026-07-30T18:17:30.687Z","primary_count":2,"removed_count":2,"review_reason":"O candidato ''Perfuração Intestinal'' para o termo parcial ''Perfuração Gástrica'' foi removido por equivalência semântica incorreta (órgãos distintos). Não houve candidatos DeCS para os outros termos primários (''Úlcera Péptica'', ''Suturas''). O único termo aprovado (''Gastroenterostomia'') é secundário e representa conceitos de alternativas incorretas, resultando em um conjunto final incoerente e sem termos primários que representem o núcleo da questão.","coerencia_geral":44,"needs_manual_review":false,"missing_primary_terms":false}'::jsonb, 25761, 706, '{"totals":{"by_agent":{"decs_classifier":{"calls":1,"input_tokens":1646,"total_tokens":3418,"output_tokens":51},"habilities_agent":{"calls":1,"input_tokens":8366,"total_tokens":8633,"output_tokens":267},"question_terms_validator":{"calls":1,"input_tokens":2914,"total_tokens":5465,"output_tokens":291},"question_themes_assigner":{"calls":1,"input_tokens":12835,"total_tokens":12932,"output_tokens":97}},"input_tokens":25761,"total_tokens":30448,"output_tokens":706,"thoughts_tokens":3981},"operations":[{"agent":"decs_classifier","model":"gemini-2.5-flash","input_tokens":1646,"total_tokens":3418,"output_tokens":51,"thoughts_tokens":1721},{"agent":"question_terms_validator","model":"gemini-2.5-flash","input_tokens":2914,"total_tokens":5465,"output_tokens":291,"thoughts_tokens":2260},{"agent":"question_themes_assigner","model":"gemini-2.5-flash","input_tokens":12835,"total_tokens":12932,"output_tokens":97},{"agent":"habilities_agent","model":"gemini-2.5-flash","input_tokens":8366,"total_tokens":8633,"output_tokens":267}],"updated_at":"2026-07-30T18:17:34.418Z","estimated_cost_usd":{"input_usd":0.007728,"total_usd":0.009493,"output_usd":0.001765}}'::jsonb)
