INSERT INTO public.questions ("id", "statement", "option_a", "option_b", "option_c", "option_d", "option_e", "correct_answer", "explanation", "tags", "images", "exam_year", "exam_board", "exam_institution", "exam_region", "exam_type", "prova_id", "numero_na_prova", "areas_conhecimento", "assuntos", "created_at", "updated_at", "anulada", "decs_terms", "ai_decs_descriptors", "ai_decs_v2", "ai_decs_classified_text", "images_meta", "competencias", "temas", "ai_habilities", "ai_question_themes", "decs_validation_meta", "input_tokens", "output_tokens", "ai_token_usage")
VALUES (1709, 'Um paciente de 55 anos diabético e hipertenso apresenta-se ao pronto-socorro com dor abdominal intensa localizada no epigástrio e em faixa nas costas, acompanhada de náuseas e vômitos. Exames laboratoriais mostram elevação de amilase e lipase. Qual é a principal hipótese diagnóstica?', 'Apendicite aguda.', 'Colecistite aguda.', 'Pancreatite aguda.', 'Úlcera duodenal perfurada.', NULL, 'C', NULL, NULL, '[]', 2025, 'ABC', NULL, 'SP', 'MASTOLOGIA', 20, 15, NULL, NULL, '2026-04-08T21:50:21.356986+00:00', '2026-08-06T18:52:01.536155+00:00', FALSE, NULL, '[{"code":"D010195","term":"Pancreatite","name_en":"Pancreatitis","tree_ids":["C06.689.750"],"hierarchy_path":"Doenças › C06.689.750","branches":[{"tree_id":"C06.689.750","hierarchy_path":"Doenças › C06.689.750"}],"search_method":"text","role":"primary","scope_note":"INFLAMAÇÃO do PÂNCREAS. A pancreatite é classificada como aguda, a menos que haja uma tomografia computadorizada ou achados de colangiopancreatografia endoscópica retrógrada que indiquem PANCREATITE CRÔNICA (Simpósio Internacional de Pancreatite Aguda, Atlanta, 1992). As duas formas mais comuns de pancreatite aguda são PANCREATITE ALCOÓLICA e pancreatite por cálculo biliar."},{"code":"D000681","term":"Amilases","name_en":"Amylases","tree_ids":["D08.811.277.450.066"],"hierarchy_path":"Compostos Químicos e Drogas › D08.811.277.450.066","branches":[{"tree_id":"D08.811.277.450.066","hierarchy_path":"Compostos Químicos e Drogas › D08.811.277.450.066"}],"search_method":"text","role":"secondary","scope_note":"Membro de um grupo de enzimas amilolíticas que clivam o amido, o glicogênio e alfa-1,4-glicanas afins. EC 3.2.1.-."},{"code":"D008049","term":"Lipase","name_en":"Lipase","tree_ids":["D08.811.277.352.100.400"],"hierarchy_path":"Compostos Químicos e Drogas › D08.811.277.352.100.400","branches":[{"tree_id":"D08.811.277.352.100.400","hierarchy_path":"Compostos Químicos e Drogas › D08.811.277.352.100.400"}],"search_method":"text","role":"secondary","scope_note":"Enzima da classe das hidrolases que catalisa a reação de triacilglicerol e água para produzir diacilglicerol e um ânion de ácido graxo. É produzida por glândulas na língua e pelo pâncreas e inicia a digestão de gorduras alimentares. EC 3.1.1.3."},{"code":"D015746","term":"Dor Abdominal","name_en":"Abdominal Pain","tree_ids":["C23.888.592.612.054","C23.888.821.030","F02.830.816.444.001","G11.561.790.444.001"],"hierarchy_path":"Doenças › C23.888.592.612.054","branches":[{"tree_id":"C23.888.592.612.054","hierarchy_path":"Doenças › C23.888.592.612.054"},{"tree_id":"C23.888.821.030","hierarchy_path":"Doenças › C23.888.821.030"},{"tree_id":"F02.830.816.444.001","hierarchy_path":"Psiquiatria e Psicologia › F02.830.816.444.001"},{"tree_id":"G11.561.790.444.001","hierarchy_path":"Fenômenos Biológicos › G11.561.790.444.001"}],"search_method":"text","role":"secondary","scope_note":"Sensação de desconforto, mal estar ou agonia na região abdominal."},{"code":"D003920","term":"Diabetes Mellitus","name_en":"Diabetes Mellitus","tree_ids":["C18.452.394.750","C19.246"],"hierarchy_path":"Doenças › C18.452.394.750","branches":[{"tree_id":"C18.452.394.750","hierarchy_path":"Doenças › C18.452.394.750"},{"tree_id":"C19.246","hierarchy_path":"Doenças › C19.246"}],"search_method":"text","role":"secondary","scope_note":"Grupo de transtornos heterogêneos caracterizados por HIPERGLICEMIA e INTOLERÂNCIA À GLUCOSE."},{"code":"D006973","term":"Hipertensão","name_en":"Hypertension","tree_ids":["C14.907.489"],"hierarchy_path":"Doenças › C14.907.489","branches":[{"tree_id":"C14.907.489","hierarchy_path":"Doenças › C14.907.489"}],"search_method":"text","role":"secondary","scope_note":"PRESSÃO ARTERIAL sistêmica persistentemente alta. Com base em várias medições (DETERMINAÇÃO DA PRESSÃO ARTERIAL), a hipertensão é atualmente definida como sendo a PRESSÃO SISTÓLICA repetidamente maior que 140 mm Hg ou a PRESSÃO DIASTÓLICA de 90 mm Hg ou superior."},{"code":"D041881","term":"Colecistite Aguda","name_en":"Cholecystitis, Acute","tree_ids":["C06.130.564.263.500"],"hierarchy_path":"Doenças › C06.130.564.263.500","branches":[{"tree_id":"C06.130.564.263.500","hierarchy_path":"Doenças › C06.130.564.263.500"}],"search_method":"text","role":"secondary","scope_note":"Inflamação aguda da parede da VESÍCULA BILIAR. Caracteriza-se pela presença de DOR ABDOMINAL, FEBRE e LEUCOCITOSE. A obstrução por cálculo biliar do DUCTO CÍSTICO está presente em aproximadamente 90 por cento dos casos."}]', NULL, NULL, NULL, NULL, NULL, '{"competencias":[{"competencia":"Interpretação de biomarcadores diagnósticos","conteudos":[],"id":"123","justificativa":"A elevação de amilase e lipase é um biomarcador diagnóstico crucial para a pancreatite aguda, e o candidato precisa interpretar esses resultados para confirmar a hipótese.","principal":false}],"novas_competencias":[]}', '{"temas":[{"tema":"Pancreatite","subtemas":["Pancreatite aguda"],"principal":true},{"tema":"Abdome agudo","subtemas":["Abdome agudo"],"principal":false}],"tema_principal":"Pancreatite"}', '{"source":"backfill-missing-primary-meta","kept_count":7,"dismissed_at":null,"validated_at":"2026-07-30T18:18:18.802Z","primary_count":1,"removed_count":0,"review_reason":"Nenhum descritor vetorial/API disponível para validação (apenas textuais ou lista vazia).","coerencia_geral":0,"needs_manual_review":true,"missing_primary_terms":false}'::jsonb, 22754, 324, '{"totals":{"by_agent":{"decs_classifier":{"calls":1,"input_tokens":1615,"total_tokens":2954,"output_tokens":37},"habilities_agent":{"calls":1,"input_tokens":8335,"total_tokens":8537,"output_tokens":202},"question_themes_assigner":{"calls":1,"input_tokens":12804,"total_tokens":12889,"output_tokens":85}},"input_tokens":22754,"total_tokens":24380,"output_tokens":324,"thoughts_tokens":1302},"operations":[{"agent":"decs_classifier","model":"gemini-2.5-flash","input_tokens":1615,"total_tokens":2954,"output_tokens":37,"thoughts_tokens":1302},{"agent":"question_themes_assigner","model":"gemini-2.5-flash","input_tokens":12804,"total_tokens":12889,"output_tokens":85},{"agent":"habilities_agent","model":"gemini-2.5-flash","input_tokens":8335,"total_tokens":8537,"output_tokens":202}],"updated_at":"2026-07-30T18:18:21.068Z","estimated_cost_usd":{"input_usd":0.006826,"total_usd":0.007636,"output_usd":0.00081}}'::jsonb)
