VALUES (1710, 'Durante uma cirurgia de apendicectomia, o cirurgião identifica um apêndice aparentemente normal, mas observa um espessamento do íleo terminal. Qual é a causa mais provável do espessamento?', 'Doença de Crohn.', 'Tuberculose intestinal.', 'Apendicite retrocecal.', 'Neoplasia do intestino delgado.', NULL, 'A', NULL, NULL, '[]', 2025, 'ABC', NULL, 'SP', 'MASTOLOGIA', 20, 16, NULL, NULL, '2026-04-08T21:50:21.35909+00:00', '2026-08-06T18:52:01.536155+00:00', FALSE, NULL, '[{"code":"D003424","term":"Doença de Crohn","name_en":"Crohn Disease","tree_ids":["C06.405.205.731.500","C06.405.469.432.500"],"hierarchy_path":"Doenças › C06.405.205.731.500","branches":[{"tree_id":"C06.405.205.731.500","hierarchy_path":"Doenças › C06.405.205.731.500"},{"tree_id":"C06.405.469.432.500","hierarchy_path":"Doenças › C06.405.469.432.500"}],"search_method":"text","role":"primary","scope_note":"Inflamação transmural crônica que pode envolver qualquer parte do TRATO DIGESTÓRIO desde a BOCA até o ÂNUS, principalmente encontrada no ÍLEO, CECO, e COLO. Na doença de Crohn, a inflamação que se estende através da parede intestinal da MUCOSA até a serosa, é caracteristicamente assimétrica e segmentar. GRANULOMAS epitelioides podem ser vistos em alguns pacientes."},{"code":"D007082","term":"Íleo","name_en":"Ileum","tree_ids":["A03.556.124.684.249","A03.556.249.124"],"hierarchy_path":"Anatomia › A03.556.124.684.249","branches":[{"tree_id":"A03.556.124.684.249","hierarchy_path":"Anatomia › A03.556.124.684.249"},{"tree_id":"A03.556.249.124","hierarchy_path":"Anatomia › A03.556.249.124"}],"search_method":"text","role":"primary","scope_note":"A porção distal e mais estreita do INTESTINO DELGADO, entre o JEJUNO e a VALVA ILEOCECAL do INTESTINO GROSSO."},{"code":"D001062","term":"Apendicectomia","name_en":"Appendectomy","tree_ids":["E04.210.078"],"hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.210.078","branches":[{"tree_id":"E04.210.078","hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.210.078"}],"search_method":"text","role":"secondary","scope_note":"Remoção cirúrgica do apêndice vermiforme. (Dorland, 28a ed.)"},{"code":"D014385","term":"Tuberculose Gastrointestinal","name_en":"Tuberculosis, Gastrointestinal","tree_ids":["C01.150.252.410.040.552.846.617.350","C06.405.874"],"hierarchy_path":"Doenças › C01.150.252.410.040.552.846.617.350","branches":[{"tree_id":"C01.150.252.410.040.552.846.617.350","hierarchy_path":"Doenças › C01.150.252.410.040.552.846.617.350"},{"tree_id":"C06.405.874","hierarchy_path":"Doenças › C06.405.874"}],"search_method":"text","role":"secondary","scope_note":"TUBERCULOSE que abrange qualquer região do TRATO GRASTROINTESTINAL, em sua maioria o ÍLEO distal e o CECO. Na maioria dos casos, o patógeno é o MYCOBACTERIUM TUBERCULOSIS. As características clínicas incluem DOR ABDOMINAL, FEBRE e massa palpável na área ileocecal."},{"term":"Neoplasias do Íleo","code":"D007078","tree_ids":["C04.588.274.476.411.501","C06.301.371.411.501","C06.405.249.411.501","C06.405.469.420.501","C06.405.469.491.501"],"hierarchy_path":"Doenças › C04.588.274.476.411.501","branches":[{"tree_id":"C04.588.274.476.411.501","hierarchy_path":"Doenças › C04.588.274.476.411.501"},{"tree_id":"C06.301.371.411.501","hierarchy_path":"Doenças › C06.301.371.411.501"},{"tree_id":"C06.405.249.411.501","hierarchy_path":"Doenças › C06.405.249.411.501"},{"tree_id":"C06.405.469.420.501","hierarchy_path":"Doenças › C06.405.469.420.501"},{"tree_id":"C06.405.469.491.501","hierarchy_path":"Doenças › C06.405.469.491.501"}],"scope_note":"Tumores ou câncer no ÍLEO região do intestino delgado (INTESTINO DELGADO)","name_en":"Ileal Neoplasms","search_method":"vector","role":"secondary"}]', NULL, NULL, NULL, NULL, NULL, '{"competencias":[{"competencia":"Diagnóstico diferencial","conteudos":[],"id":"67","justificativa":"A questão exige que o candidato diferencie entre várias causas possíveis de espessamento do íleo terminal, dado um apêndice normal, o que é o cerne do diagnóstico diferencial.","principal":true}],"novas_competencias":[]}', '{"temas":[{"tema":"Doenças inflamatórias intestinais","subtemas":["Doenças inflamatórias intestinais"],"principal":true},{"tema":"Apendicite aguda","subtemas":["Apendicite aguda"],"principal":false}],"tema_principal":"Doenças inflamatórias intestinais"}', '{"source":"backfill-missing-primary-meta","kept_count":5,"dismissed_at":null,"validated_at":"2026-07-30T18:19:17.068Z","primary_count":2,"removed_count":0,"review_reason":"Nenhum termo PRIMARY foi aprovado no conjunto final. O único termo candidato aprovado (''Neoplasias do Íleo'') representa uma alternativa de diagnóstico na questão, mas não o conceito central (''Doença de Crohn'') que é o gabarito.","coerencia_geral":64,"needs_manual_review":false,"missing_primary_terms":false}'::jsonb, 25279, 527, '{"totals":{"by_agent":{"decs_classifier":{"calls":1,"input_tokens":1589,"total_tokens":2497,"output_tokens":34},"habilities_agent":{"calls":1,"input_tokens":8309,"total_tokens":8514,"output_tokens":205},"question_terms_validator":{"calls":1,"input_tokens":2603,"total_tokens":4778,"output_tokens":209},"question_themes_assigner":{"calls":1,"input_tokens":12778,"total_tokens":12857,"output_tokens":79}},"input_tokens":25279,"total_tokens":28646,"output_tokens":527,"thoughts_tokens":2840},"operations":[{"agent":"decs_classifier","model":"gemini-2.5-flash","input_tokens":1589,"total_tokens":2497,"output_tokens":34,"thoughts_tokens":874},{"agent":"question_terms_validator","model":"gemini-2.5-flash","input_tokens":2603,"total_tokens":4778,"output_tokens":209,"thoughts_tokens":1966},{"agent":"question_themes_assigner","model":"gemini-2.5-flash","input_tokens":12778,"total_tokens":12857,"output_tokens":79},{"agent":"habilities_agent","model":"gemini-2.5-flash","input_tokens":8309,"total_tokens":8514,"output_tokens":205}],"updated_at":"2026-07-30T18:19:19.913Z","estimated_cost_usd":{"input_usd":0.007584,"total_usd":0.008901,"output_usd":0.001318}}'::jsonb)
