VALUES (1711, 'Em um paciente politraumatizado, com fraturas pélvica e sinais de choque hipovolêmica, qual é a primeira medida mais adequada?', 'Reposição volêmica com solução fisiológica.', 'Estabilização/fixação externa da pelve.', 'Hemotransfusão com concentrado de hemácias.', 'Administração de ácido tranexâmico.', NULL, 'B', NULL, NULL, '[]', 2025, 'ABC', NULL, 'SP', 'MASTOLOGIA', 20, 17, NULL, NULL, '2026-04-08T21:50:21.362303+00:00', '2026-08-06T18:52:01.536155+00:00', FALSE, NULL, '[{"code":"D012769","term":"Choque","name_en":"Shock","tree_ids":["C23.550.835"],"hierarchy_path":"Doenças › C23.550.835","branches":[{"tree_id":"C23.550.835","hierarchy_path":"Doenças › C23.550.835"}],"search_method":"text","role":"primary","scope_note":"Afecção manifestada por falha na perfusão ou oxigenação de órgãos vitais."},{"term":"Fixadores Externos","code":"D016267","tree_ids":["E07.858.442.660.430","E07.858.690.725.430"],"hierarchy_path":"Técnicas e Equipamentos Analíticos › E07.858.442.660.430","branches":[{"tree_id":"E07.858.442.660.430","hierarchy_path":"Técnicas e Equipamentos Analíticos › E07.858.442.660.430"},{"tree_id":"E07.858.690.725.430","hierarchy_path":"Técnicas e Equipamentos Analíticos › E07.858.690.725.430"}],"scope_note":"Dispositivos externos que mantêm fios ou pinos que são colocados em um ou ambos os córtex de osso para manter a posição de uma fratura no alinhamento apropriado. Esses dispositivos permitem fácil acesso aos ferimentos, ajustamento durante o curso de cicatrização e uso mais funcional dos membros envolvidos.","name_en":"External Fixators","search_method":"vector","role":"primary"},{"code":"D009104","term":"Traumatismo Múltiplo","name_en":"Multiple Trauma","tree_ids":["C26.640"],"hierarchy_path":"Doenças › C26.640","branches":[{"tree_id":"C26.640","hierarchy_path":"Doenças › C26.640"}],"search_method":"text","role":"secondary","scope_note":"Múltiplos traumatismos ou danos físicos que ocorrem simultaneamente."},{"code":"D005440","term":"Hidratação","name_en":"Fluid Therapy","tree_ids":["E02.319.360"],"hierarchy_path":"Técnicas e Equipamentos Analíticos › E02.319.360","branches":[{"tree_id":"E02.319.360","hierarchy_path":"Técnicas e Equipamentos Analíticos › E02.319.360"}],"search_method":"text","role":"secondary","scope_note":"Terapia cujo objetivo básico é restaurar o volume e a composição dos líquidos corporais aos níveis normais, relacionados ao EQUILÍBRIO HIDROELETROLÍTICO. Os líquidos podem ser administrados por via intravenosa, oral, gavagem intermitente ou por HIPODERMÓCLISE."},{"code":"D001803","term":"Transfusão de Sangue","name_en":"Blood Transfusion","tree_ids":["E02.095.135"],"hierarchy_path":"Técnicas e Equipamentos Analíticos › E02.095.135","branches":[{"tree_id":"E02.095.135","hierarchy_path":"Técnicas e Equipamentos Analíticos › E02.095.135"}],"search_method":"text","role":"secondary","scope_note":"A introdução de sangue total ou componente de sangue diretamente dentro da corrente sanguínea. (Dorland, 28a ed)"},{"code":"D014148","term":"Ácido Tranexâmico","name_en":"Tranexamic Acid","tree_ids":["D02.241.223.268.860"],"hierarchy_path":"Compostos Químicos e Drogas › D02.241.223.268.860","branches":[{"tree_id":"D02.241.223.268.860","hierarchy_path":"Compostos Químicos e Drogas › D02.241.223.268.860"}],"search_method":"text","role":"secondary","scope_note":"Antifibrinolítico hemostático utilizado em hemorragia grave."}]', NULL, NULL, NULL, NULL, NULL, '{"competencias":[{"competencia":"Manejo de emergência","conteudos":[],"id":"116","justificativa":"A questão exige a definição da primeira medida mais adequada em um cenário de emergência com paciente politraumatizado e choque hipovolêmico, o que se enquadra diretamente no manejo de emergência e priorização de intervenções.","principal":true},{"competencia":"Classificação de gravidade","conteudos":[],"id":"113","justificativa":"O candidato precisa reconhecer a gravidade do quadro (politraumatizado, fraturas pélvicas, choque hipovolêmico) para entender a urgência e a necessidade de intervenções rápidas.","principal":false}],"novas_competencias":[]}', '{"temas":[{"tema":"Trauma","subtemas":["Trauma abdominal fechado","Lesão vascular"],"principal":true},{"tema":"Trauma pélvico","subtemas":["Trauma pélvico"],"principal":false},{"tema":"Choque","subtemas":["Choque"],"principal":false},{"tema":"Urgência e emergência","subtemas":["Avaliação inicial do paciente grave (ABCDE, ATLS)"],"principal":false}],"tema_principal":"Trauma"}', '{"source":"backfill-missing-primary-meta","kept_count":6,"dismissed_at":null,"validated_at":"2026-07-30T18:20:15.884Z","primary_count":2,"removed_count":1,"review_reason":null,"coerencia_geral":64,"needs_manual_review":false,"missing_primary_terms":false}'::jsonb, 25467, 724, '{"totals":{"by_agent":{"decs_classifier":{"calls":1,"input_tokens":1590,"total_tokens":3415,"output_tokens":49},"habilities_agent":{"calls":1,"input_tokens":8310,"total_tokens":8578,"output_tokens":268},"question_terms_validator":{"calls":1,"input_tokens":2788,"total_tokens":4667,"output_tokens":232},"question_themes_assigner":{"calls":1,"input_tokens":12779,"total_tokens":12954,"output_tokens":175}},"input_tokens":25467,"total_tokens":29614,"output_tokens":724,"thoughts_tokens":3423},"operations":[{"agent":"decs_classifier","model":"gemini-2.5-flash","input_tokens":1590,"total_tokens":3415,"output_tokens":49,"thoughts_tokens":1776},{"agent":"question_terms_validator","model":"gemini-2.5-flash","input_tokens":2788,"total_tokens":4667,"output_tokens":232,"thoughts_tokens":1647},{"agent":"question_themes_assigner","model":"gemini-2.5-flash","input_tokens":12779,"total_tokens":12954,"output_tokens":175},{"agent":"habilities_agent","model":"gemini-2.5-flash","input_tokens":8310,"total_tokens":8578,"output_tokens":268}],"updated_at":"2026-07-30T18:20:19.038Z","estimated_cost_usd":{"input_usd":0.00764,"total_usd":0.00945,"output_usd":0.00181}}'::jsonb)
