VALUES (1712, 'Um paciente com história de colecistectomia há três dias apresenta dor abdominal intensa febre e sinais de peritonite. Qual é o diagnóstico mais provável?', 'Perfuração intestinal.', 'Hemoperitônio.', 'Abscesso sub-hepático.', 'Bile leak (fuga de bile).', NULL, 'D', NULL, NULL, '[]', 2025, 'ABC', NULL, 'SP', 'MASTOLOGIA', 20, 18, NULL, NULL, '2026-04-08T21:50:21.365165+00:00', '2026-08-06T18:52:01.536155+00:00', FALSE, NULL, '[{"code":"D002763","term":"Colecistectomia","name_en":"Cholecystectomy","tree_ids":["E04.210.120.172"],"hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.210.120.172","branches":[{"tree_id":"E04.210.120.172","hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.210.120.172"}],"search_method":"text","role":"primary","scope_note":"Remoção cirúrgica da VESÍCULA BILIAR."},{"code":"D001658","term":"Fístula Biliar","name_en":"Biliary Fistula","tree_ids":["C06.267.150","C23.300.575.185.150"],"hierarchy_path":"Doenças › C06.267.150","branches":[{"tree_id":"C06.267.150","hierarchy_path":"Doenças › C06.267.150"},{"tree_id":"C23.300.575.185.150","hierarchy_path":"Doenças › C23.300.575.185.150"}],"search_method":"text","role":"primary","scope_note":"Passagem anormal em qualquer órgão do trato biliar ou entre órgãos biliares e outros órgãos."},{"code":"D010538","term":"Peritonite","name_en":"Peritonitis","tree_ids":["C01.463.600","C06.844.640"],"hierarchy_path":"Doenças › C01.463.600","branches":[{"tree_id":"C01.463.600","hierarchy_path":"Doenças › C01.463.600"},{"tree_id":"C06.844.640","hierarchy_path":"Doenças › C06.844.640"}],"search_method":"text","role":"primary","scope_note":"INFLAMAÇÃO do PERITÔNIO, que reveste a CAVIDADE ABDOMINAL, em consequência de processos infecciosos, autoimunes ou químicos. A peritonite primária é decorrente da infecção na CAVIDADE PERITONEAL através da disseminação sanguínea ou linfática sem uma origem intra-abdominal. A peritonite secundária se origina na própria CAVIDADE ABDOMINAL através de RUPTURAS ou ABSCESSO de órgãos intra-abdominais."},{"code":"D015746","term":"Dor Abdominal","name_en":"Abdominal Pain","tree_ids":["C23.888.592.612.054","C23.888.821.030","F02.830.816.444.001","G11.561.790.444.001"],"hierarchy_path":"Doenças › C23.888.592.612.054","branches":[{"tree_id":"C23.888.592.612.054","hierarchy_path":"Doenças › C23.888.592.612.054"},{"tree_id":"C23.888.821.030","hierarchy_path":"Doenças › C23.888.821.030"},{"tree_id":"F02.830.816.444.001","hierarchy_path":"Psiquiatria e Psicologia › F02.830.816.444.001"},{"tree_id":"G11.561.790.444.001","hierarchy_path":"Fenômenos Biológicos › G11.561.790.444.001"}],"search_method":"text","role":"secondary","scope_note":"Sensação de desconforto, mal estar ou agonia na região abdominal."},{"code":"D005334","term":"Febre","name_en":"Fever","tree_ids":["C23.888.119.344"],"hierarchy_path":"Doenças › C23.888.119.344","branches":[{"tree_id":"C23.888.119.344","hierarchy_path":"Doenças › C23.888.119.344"}],"search_method":"text","role":"secondary","scope_note":"Elevação anormal da temperatura corporal, geralmente como resultado de um processo patológico."},{"code":"D007416","term":"Perfuração Intestinal","name_en":"Intestinal Perforation","tree_ids":["C06.405.469.557"],"hierarchy_path":"Doenças › C06.405.469.557","branches":[{"tree_id":"C06.405.469.557","hierarchy_path":"Doenças › C06.405.469.557"}],"search_method":"text","role":"secondary","scope_note":"Abertura ou penetração através da parede do INTESTINO."},{"code":"D006465","term":"Hemoperitônio","name_en":"Hemoperitoneum","tree_ids":["C06.844.400","C23.550.414.888"],"hierarchy_path":"Doenças › C06.844.400","branches":[{"tree_id":"C06.844.400","hierarchy_path":"Doenças › C06.844.400"},{"tree_id":"C23.550.414.888","hierarchy_path":"Doenças › C23.550.414.888"}],"search_method":"text","role":"secondary","scope_note":"Acúmulos de sangue na CAVIDADE PERITONEAL devido a HEMORRAGIA interna."},{"code":"D013369","term":"Abscesso Subfrênico","name_en":"Subphrenic Abscess","tree_ids":["C01.463.600.500","C01.830.025.020.810","C06.844.640.500"],"hierarchy_path":"Doenças › C01.463.600.500","branches":[{"tree_id":"C01.463.600.500","hierarchy_path":"Doenças › C01.463.600.500"},{"tree_id":"C01.830.025.020.810","hierarchy_path":"Doenças › C01.830.025.020.810"},{"tree_id":"C06.844.640.500","hierarchy_path":"Doenças › C06.844.640.500"}],"search_method":"text","role":"secondary","scope_note":"Acúmulo de exudatos purulentos abaixo do DIAFRAGMA, também conhecido como abscesso abdominal superior. Geralmente está associado com PERITONITE ou infecções pós-operatórias."}]', NULL, NULL, NULL, NULL, NULL, '{"competencias":[{"competencia":"Diagnóstico diferencial","conteudos":[],"id":"67","justificativa":"O candidato precisa diferenciar entre as possíveis causas de peritonite pós-colecistectomia, como perfuração, hemoperitônio, abscesso e fuga de bile, para chegar ao diagnóstico mais provável.","principal":false}],"novas_competencias":[]}', '{"temas":[{"tema":"Doenças das vias biliares","subtemas":["Colecistite","Lesões iatrogênicas das vias biliares"],"principal":true},{"tema":"Abdome agudo","subtemas":["Abdome agudo"],"principal":false},{"tema":"Perioperatório","subtemas":["Complicações pós-operatórias e profilaxia de TEV"],"principal":false}],"tema_principal":"Doenças das vias biliares"}', '{"source":"backfill-missing-primary-meta","kept_count":8,"dismissed_at":null,"validated_at":"2026-07-30T18:20:46.284Z","primary_count":3,"removed_count":0,"review_reason":"Nenhum descritor vetorial/API disponível para validação (apenas textuais ou lista vazia).","coerencia_geral":0,"needs_manual_review":true,"missing_primary_terms":false}'::jsonb, 22637, 486, '{"totals":{"by_agent":{"decs_classifier":{"calls":1,"input_tokens":1576,"total_tokens":2822,"output_tokens":45},"habilities_agent":{"calls":1,"input_tokens":8296,"total_tokens":8581,"output_tokens":285},"question_themes_assigner":{"calls":1,"input_tokens":12765,"total_tokens":12921,"output_tokens":156}},"input_tokens":22637,"total_tokens":24324,"output_tokens":486,"thoughts_tokens":1201},"operations":[{"agent":"decs_classifier","model":"gemini-2.5-flash","input_tokens":1576,"total_tokens":2822,"output_tokens":45,"thoughts_tokens":1201},{"agent":"question_themes_assigner","model":"gemini-2.5-flash","input_tokens":12765,"total_tokens":12921,"output_tokens":156},{"agent":"habilities_agent","model":"gemini-2.5-flash","input_tokens":8296,"total_tokens":8581,"output_tokens":285}],"updated_at":"2026-07-30T18:20:50.770Z","estimated_cost_usd":{"input_usd":0.006791,"total_usd":0.008006,"output_usd":0.001215}}'::jsonb)
