VALUES (1713, 'Um homem de 60 anos com histórico de cirrose hepática por hepatite C apresenta-se com um quadro de hematêmese e melena. Ao exame físico, ele está hipotenso, com sinais de choque hipovolêmico. Qual é a causa mais provável para o quadro hemorrágico?', 'Úlcera gástrica.', 'Varizes esdofágicas rompidas.', 'Síndrome de Mallory-Weiss.', 'úlcera duodenal.', NULL, 'B', NULL, NULL, '[]', 2025, 'ABC', NULL, 'SP', 'MASTOLOGIA', 20, 19, NULL, NULL, '2026-04-08T21:50:21.367139+00:00', '2026-08-06T18:52:01.536155+00:00', FALSE, NULL, '[{"code":"D008103","term":"Cirrose Hepática","name_en":"Liver Cirrhosis","tree_ids":["C06.552.630","C23.550.355.412"],"hierarchy_path":"Doenças › C06.552.630","branches":[{"tree_id":"C06.552.630","hierarchy_path":"Doenças › C06.552.630"},{"tree_id":"C23.550.355.412","hierarchy_path":"Doenças › C23.550.355.412"}],"search_method":"text","role":"primary","scope_note":"A doença hepática na qual a microcirculação normal, a anatomia vascular no geral, e a arquitetura hepática têm sido destruídas e alteradas de modo variado por septos fibrosos ao redor de nódulos parenquimatosos regenerados ou em regeneração."},{"code":"D004932","term":"Varizes Esofágicas e Gástricas","name_en":"Esophageal and Gastric Varices","tree_ids":["C06.405.117.240","C06.552.494.414"],"hierarchy_path":"Doenças › C06.405.117.240","branches":[{"tree_id":"C06.405.117.240","hierarchy_path":"Doenças › C06.405.117.240"},{"tree_id":"C06.552.494.414","hierarchy_path":"Doenças › C06.552.494.414"}],"search_method":"text","role":"primary","scope_note":"Vasos sanguíneos dilatados no ESÔFAGO ou FUNDO DO ESTÔMAGO que desviam o sangue da circulação portal (SISTEMA PORTA) para a circulação venosa sistêmica. São observadas com frequência em indivíduos com HIPERTENSÃO PORTAL."},{"code":"D006471","term":"Hemorragia Gastrointestinal","name_en":"Gastrointestinal Hemorrhage","tree_ids":["C06.405.227","C23.550.414.788"],"hierarchy_path":"Doenças › C06.405.227","branches":[{"tree_id":"C06.405.227","hierarchy_path":"Doenças › C06.405.227"},{"tree_id":"C23.550.414.788","hierarchy_path":"Doenças › C23.550.414.788"}],"search_method":"text","role":"primary","scope_note":"Sangramento em qualquer segmento do TRATO GASTROINTESTINAL do ESÔFAGO até o RETO."},{"code":"D006526","term":"Hepatite C","name_en":"Hepatitis C","tree_ids":["C01.221.250.750","C01.925.440.440","C01.925.782.350.350","C06.552.380.705.440"],"hierarchy_path":"Doenças › C01.221.250.750","branches":[{"tree_id":"C01.221.250.750","hierarchy_path":"Doenças › C01.221.250.750"},{"tree_id":"C01.925.440.440","hierarchy_path":"Doenças › C01.925.440.440"},{"tree_id":"C01.925.782.350.350","hierarchy_path":"Doenças › C01.925.782.350.350"},{"tree_id":"C06.552.380.705.440","hierarchy_path":"Doenças › C06.552.380.705.440"}],"search_method":"text","role":"secondary","scope_note":"INFLAMAÇÃO do FÍGADO em humanos causada por VIRUS DA HEPATITE C, um virus com RNA de fita única. Seu período de incubação é de 30 a 90 dias. A hepatite C é principalmente transmitida por sangue contaminado por via parenteral e está, com frequência, associada com transfusões e abuso de drogas. Entretanto, em vários casos a fonte da infecção da hepatite C é desconhecida."},{"code":"D012769","term":"Choque","name_en":"Shock","tree_ids":["C23.550.835"],"hierarchy_path":"Doenças › C23.550.835","branches":[{"tree_id":"C23.550.835","hierarchy_path":"Doenças › C23.550.835"}],"search_method":"text","role":"secondary","scope_note":"Afecção manifestada por falha na perfusão ou oxigenação de órgãos vitais."},{"term":"Hematemese","code":"D006396","tree_ids":["C06.405.227.400","C23.550.414.788.400","C23.888.821.937.019"],"hierarchy_path":"Doenças › C06.405.227.400","branches":[{"tree_id":"C06.405.227.400","hierarchy_path":"Doenças › C06.405.227.400"},{"tree_id":"C23.550.414.788.400","hierarchy_path":"Doenças › C23.550.414.788.400"},{"tree_id":"C23.888.821.937.019","hierarchy_path":"Doenças › C23.888.821.937.019"}],"scope_note":"Vômito de sangue que apresenta característica de cores vermelho claro ou café. Geralmente indica sangramento do TRATO GASTROINTESTINAL SUPERIOR.","name_en":"Hematemesis","search_method":"vector","role":"secondary"},{"code":"D008551","term":"Melena","name_en":"Melena","tree_ids":["A12.459.764","C06.405.227.600","C23.550.414.788.600"],"hierarchy_path":"Anatomia › A12.459.764","branches":[{"tree_id":"A12.459.764","hierarchy_path":"Anatomia › A12.459.764"},{"tree_id":"C06.405.227.600","hierarchy_path":"Doenças › C06.405.227.600"},{"tree_id":"C23.550.414.788.600","hierarchy_path":"Doenças › C23.550.414.788.600"}],"search_method":"text","role":"secondary","scope_note":"FEZES pretas, alcatroadas e fétidas, contendo sangue degradado."},{"code":"D013276","term":"Úlcera Gástrica","name_en":"Stomach Ulcer","tree_ids":["C06.405.469.275.800.849","C06.405.748.586.849"],"hierarchy_path":"Doenças › C06.405.469.275.800.849","branches":[{"tree_id":"C06.405.469.275.800.849","hierarchy_path":"Doenças › C06.405.469.275.800.849"},{"tree_id":"C06.405.748.586.849","hierarchy_path":"Doenças › C06.405.748.586.849"}],"search_method":"text","role":"secondary","scope_note":"Ulceração da MUCOSA GÁSTRICA devido contato com SUCO GÁSTRICO. Frequentemente está associada com infecção por HELICOBACTER PYLORI ou consumo de drogas anti-inflamatórias não esteroides (AGENTES ANTI-INFLAMATORIOS NÃO ESTEROIDES)."},{"code":"D008309","term":"Síndrome de Mallory-Weiss","name_en":"Mallory-Weiss Syndrome","tree_ids":["C06.405.117.468.524"],"hierarchy_path":"Doenças › C06.405.117.468.524","branches":[{"tree_id":"C06.405.117.468.524","hierarchy_path":"Doenças › C06.405.117.468.524"}],"search_method":"text","role":"secondary","scope_note":"Afecção caracterizada por laceração da mucosa da JUNÇÃO ESOFAGOGÁSTRICA, às vezes, com HEMATEMESE. É causada tipicamente por fortes ataques de ânsia ou VÔMITO."}]', NULL, NULL, NULL, NULL, NULL, '{"competencias":[{"competencia":"Diagnóstico diferencial","conteudos":[],"id":"67","justificativa":"O candidato precisa diferenciar entre as causas de hemorragia digestiva alta em um paciente cirrótico, priorizando as varizes esofágicas rompidas como a mais provável dado o histórico e a gravidade.","principal":false},{"competencia":"Classificação de gravidade","conteudos":[],"id":"113","justificativa":"A presença de hipotensão e sinais de choque hipovolêmico indica a necessidade de classificar a gravidade do quadro hemorrágico, o que influencia a priorização diagnóstica e terapêutica.","principal":false}],"novas_competencias":[]}', '{"temas":[{"tema":"Cirrose","subtemas":["Varizes esofágicas","Causas e complicações da cirrose"],"principal":true},{"tema":"Hemorragia digestiva alta","subtemas":["Hemorragia digestiva alta"],"principal":false},{"tema":"Choque","subtemas":["Choque"],"principal":false}],"tema_principal":"Cirrose"}', '{"source":"backfill-missing-primary-meta","kept_count":9,"dismissed_at":null,"validated_at":"2026-07-30T18:21:34.108Z","primary_count":3,"removed_count":0,"review_reason":"Nenhum termo candidato para os conceitos primários da questão (Cirrose Hepática, Varizes Esofágicas, Hemorragia Gastrointestinal) foi fornecido. O único termo aprovado é secundário, resultando em falta de representação do núcleo da questão.","coerencia_geral":64,"needs_manual_review":false,"missing_primary_terms":false}'::jsonb, 25417, 668, '{"totals":{"by_agent":{"decs_classifier":{"calls":1,"input_tokens":1613,"total_tokens":2997,"output_tokens":57},"habilities_agent":{"calls":1,"input_tokens":8333,"total_tokens":8608,"output_tokens":275},"question_terms_validator":{"calls":1,"input_tokens":2669,"total_tokens":4193,"output_tokens":213},"question_themes_assigner":{"calls":1,"input_tokens":12802,"total_tokens":12925,"output_tokens":123}},"input_tokens":25417,"total_tokens":28723,"output_tokens":668,"thoughts_tokens":2638},"operations":[{"agent":"decs_classifier","model":"gemini-2.5-flash","input_tokens":1613,"total_tokens":2997,"output_tokens":57,"thoughts_tokens":1327},{"age