VALUES (1714, 'Durante uma cirurgia de Whipple para tratamento de adenocarcinoma de cabeça de pâncreas, uma das complicações mais temidas é a fístula pancreática pós-operatória. Qual dos seguintes fatores aumenta o risco de fistula pancreática pós-cirúrgica?', 'Diâmetro do ducto pancreático maior que 5 mm.', 'Consistência do pâncreas amolecida.', 'Nivel de albumina elevado.', 'Idade acima de 40 anos.', NULL, 'B', NULL, NULL, '[]', 2025, 'ABC', NULL, 'SP', 'MASTOLOGIA', 20, 20, NULL, NULL, '2026-04-08T21:50:21.369858+00:00', '2026-08-06T18:52:01.536155+00:00', FALSE, NULL, '[{"code":"D010190","term":"Neoplasias Pancreáticas","name_en":"Pancreatic Neoplasms","tree_ids":["C04.588.274.761","C04.588.322.475","C06.301.761","C06.689.667","C19.344.421"],"hierarchy_path":"Doenças › C04.588.274.761","branches":[{"tree_id":"C04.588.274.761","hierarchy_path":"Doenças › C04.588.274.761"},{"tree_id":"C04.588.322.475","hierarchy_path":"Doenças › C04.588.322.475"},{"tree_id":"C06.301.761","hierarchy_path":"Doenças › C06.301.761"},{"tree_id":"C06.689.667","hierarchy_path":"Doenças › C06.689.667"},{"tree_id":"C19.344.421","hierarchy_path":"Doenças › C19.344.421"}],"search_method":"text","role":"primary","scope_note":"Tumores ou câncer do PÂNCREAS. Dependendo dos tipos de CÉLULAS das ILHOTAS PANCREÁTICAS presentes nos tumores, vários hormônios podem ser secretados: GLUCAGON das CÉLULAS PANCREÁTICAS ALFA, INSULINA das CÉLULAS PANCREÁTICAS BETA e SOMATOSTATINA das CÉLULAS SECRETORAS DE SOMATOSTATINA. A maioria é maligna, exceto os tumores produtores de insulina (INSULINOMA)."},{"code":"D016577","term":"Pancreaticoduodenectomia","name_en":"Pancreaticoduodenectomy","tree_ids":["E04.210.760"],"hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.210.760","branches":[{"tree_id":"E04.210.760","hierarchy_path":"Técnicas e Equipamentos Analíticos › E04.210.760"}],"search_method":"text","role":"primary","scope_note":"Excisão da cabeça do pâncreas e da alça envolvendo o duodeno, ao qual está conectado."},{"code":"D010185","term":"Fístula Pancreática","name_en":"Pancreatic Fistula","tree_ids":["C06.267.775","C06.689.583","C23.300.575.185.775"],"hierarchy_path":"Doenças › C06.267.775","branches":[{"tree_id":"C06.267.775","hierarchy_path":"Doenças › C06.267.775"},{"tree_id":"C06.689.583","hierarchy_path":"Doenças › C06.689.583"},{"tree_id":"C23.300.575.185.775","hierarchy_path":"Doenças › C23.300.575.185.775"}],"search_method":"text","role":"primary","scope_note":"Via anormal comunicando com o PÂNCREAS."},{"code":"D010179","term":"Pâncreas","name_en":"Pancreas","tree_ids":["A03.734"],"hierarchy_path":"Anatomia › A03.734","branches":[{"tree_id":"A03.734","hierarchy_path":"Anatomia › A03.734"}],"search_method":"text","role":"secondary","scope_note":"Órgão nodular no ABDOME que abriga uma mistura de GLÂNDULAS ENDÓCRINAS e GLÂNDULAS EXÓCRINAS. A pequena porção endócrina consiste das ILHOTAS DE LANGERHANS que secretam vários hormônios na corrente sanguinea. A grande porção exócrina (PÂNCREAS EXÓCRINO) é uma glândula acinar composta que secreta várias enzimas digestivas no sistema de ductos que desemboca no DUODENO."},{"code":"D000418","term":"Albuminas","name_en":"Albumins","tree_ids":["D12.776.034"],"hierarchy_path":"Compostos Químicos e Drogas › D12.776.034","branches":[{"tree_id":"D12.776.034","hierarchy_path":"Compostos Químicos e Drogas › D12.776.034"}],"search_method":"text","role":"secondary","scope_note":"Proteínas solúveis em água encontradas na clara do ovo, sangue, linfa e outros tecidos e fluídos. Coagulam quando aquecidas."},{"code":"D010183","term":"Ductos Pancreáticos","name_en":"Pancreatic Ducts","tree_ids":["A03.734.667"],"hierarchy_path":"Anatomia › A03.734.667","branches":[{"tree_id":"A03.734.667","hierarchy_path":"Anatomia › A03.734.667"}],"search_method":"text","role":"secondary","scope_note":"Ductos que coletam SUCO PANCREÁTICO do PÂNCREAS e o fornecem ao DUODENO."}]', NULL, NULL, NULL, NULL, NULL, '{"competencias":[{"competencia":"Identificação de mecanismo da doença","conteudos":[],"id":"95","justificativa":"Para entender por que a consistência amolecida do pâncreas aumenta o risco de fístula, o candidato precisa ter conhecimento do mecanismo fisiopatológico envolvido na cicatrização e integridade do tecido pancreático após a cirurgia.","principal":false}],"novas_competencias":[]}', '{"temas":[{"tema":"Tumor de pâncreas","subtemas":["Tumor de pâncreas"],"principal":true},{"tema":"Perioperatório","subtemas":["Complicações pós-operatórias e profilaxia de TEV"],"principal":false}],"tema_principal":"Tumor de pâncreas"}', '{"source":"backfill-missing-primary-meta","kept_count":6,"dismissed_at":null,"validated_at":"2026-07-30T18:22:19.171Z","primary_count":3,"removed_count":0,"review_reason":"Nenhum descritor vetorial/API disponível para validação (apenas textuais ou lista vazia).","coerencia_geral":0,"needs_manual_review":true,"missing_primary_terms":false}'::jsonb, 22748, 349, '{"totals":{"by_agent":{"decs_classifier":{"calls":1,"input_tokens":1613,"total_tokens":2699,"output_tokens":40},"habilities_agent":{"calls":1,"input_tokens":8333,"total_tokens":8545,"output_tokens":212},"question_themes_assigner":{"calls":1,"input_tokens":12802,"total_tokens":12899,"output_tokens":97}},"input_tokens":22748,"total_tokens":24143,"output_tokens":349,"thoughts_tokens":1046},"operations":[{"agent":"decs_classifier","model":"gemini-2.5-flash","input_tokens":1613,"total_tokens":2699,"output_tokens":40,"thoughts_tokens":1046},{"agent":"question_themes_assigner","model":"gemini-2.5-flash","input_tokens":12802,"total_tokens":12899,"output_tokens":97},{"agent":"habilities_agent","model":"gemini-2.5-flash","input_tokens":8333,"total_tokens":8545,"output_tokens":212}],"updated_at":"2026-07-30T18:22:21.971Z","estimated_cost_usd":{"input_usd":0.006824,"total_usd":0.007697,"output_usd":0.000873}}'::jsonb)
